# --- Review HUD management ---
_REVIEW_HUD = None  # type: ignore
_REVIEW_CONTEXT_STRIP = None  # type: ignore
_FARMING_BADGE = None  # type: ignore
_DISTRACTION_BADGE = None  # type: ignore
_FARM_STATUS_DIALOG = None  # type: ignore


def _raise_exp_popup() -> None:
    """Keep an in-flight XP bubble above the HUD cluster.

    Sibling paint order is creation order and the popup is created first, at
    profile load; the HUD, context strip, and farming badge each re-raise
    themselves on every reviewer_question and reviewer_answer, so a one-shot
    raise_() inside show_text() does not survive the next answered card.
    """
    try:
        popup = getattr(mw, "exp_popup", None)
        if popup is not None and popup.isVisible():
            popup.raise_()
    except Exception:
        pass


def _reposition_hud_side_badges() -> None:
    """Lay the interactive HUD siblings out as one left-hand column.

    Farming and D&D appear and disappear independently, so the cluster geometry
    lives in one place: Farming on top, D&D under it, the whole column centred
    on the HUD and falling back to above the HUD near the left screen edge.
    """
    try:
        badges = [
            badge
            for badge in (_FARMING_BADGE, _DISTRACTION_BADGE)
            if badge is not None and badge.isVisible()
        ]
        if not badges:
            return
        parent = badges[0].parent() or mw
        if parent is None:
            return
        for badge in badges:
            badge.adjustSize()
        spacing = 6
        width = max(badge.width() for badge in badges)
        total = sum(badge.height() for badge in badges) + spacing * (len(badges) - 1)
        hud = _REVIEW_HUD
        if hud is not None and hud.isVisible():
            x = hud.x() - width - 8
            y = hud.y() + max(0, (hud.height() - total) // 2)
            if x < 8:
                x = hud.x()
                y = max(8, hud.y() - total - 6)
        else:
            x = max(8, (parent.width() - width) // 2 - 210)
            y = max(8, parent.height() - total - 72)
        for badge in badges:
            badge.move(x, y)
            y += badge.height() + spacing
        if _FARM_STATUS_DIALOG is not None and _FARM_STATUS_DIALOG.isVisible():
            _position_farming_status_dialog()
    except Exception:
        pass


def _cleanup_extra_huds() -> None:
    """Hide and delete any stray HUD widgets from prior versions or reloads.
    Ensures only a single child HUD exists under mw and no top-level HUDs remain.
    """
    if not HAS_QT:
        return
    try:
        try:
            from aqt.qt import QApplication  # type: ignore
        except Exception:
            QApplication = None  # type: ignore
        # Remove top-level HUDs that may have been created with ToolTip flags
        if QApplication is not None:
            for w in QApplication.topLevelWidgets():
                try:
                    name = getattr(w, "objectName", lambda: "")()
                    if name in {"AnkiScapeReviewHUD", "AnkiScapeReviewContextStrip", "AnkiScapeFarmingBadge", "AnkiScapeDistractionBadge", "farmingStatusDialog"}:
                        current = {
                            "AnkiScapeReviewHUD": _REVIEW_HUD,
                            "AnkiScapeReviewContextStrip": _REVIEW_CONTEXT_STRIP,
                            "AnkiScapeFarmingBadge": _FARMING_BADGE,
                            "AnkiScapeDistractionBadge": _DISTRACTION_BADGE,
                        }.get(name)
                        if current is None or w is not current:
                            try:
                                w.hide()
                            except Exception:
                                pass
                            try:
                                w.deleteLater()
                            except Exception:
                                pass
                except Exception:
                    pass
        # Also remove duplicate children under mw
        par = mw
        if par is not None:
            from aqt.qt import QWidget as _QW  # type: ignore
            for child in par.findChildren(_QW, "AnkiScapeReviewHUD"):
                if _REVIEW_HUD is None or child is not _REVIEW_HUD:
                    try:
                        child.hide()
                    except Exception:
                        pass
                    try:
                        child.deleteLater()
                    except Exception:
                        pass
            for child in par.findChildren(_QW, "AnkiScapeReviewContextStrip"):
                if _REVIEW_CONTEXT_STRIP is None or child is not _REVIEW_CONTEXT_STRIP:
                    try:
                        child.hide()
                        child.deleteLater()
                    except Exception:
                        pass
            for child in par.findChildren(_QW, "AnkiScapeDistractionBadge"):
                if _DISTRACTION_BADGE is None or child is not _DISTRACTION_BADGE:
                    try:
                        child.hide()
                        child.deleteLater()
                    except Exception:
                        pass
            for child in par.findChildren(_QW, "AnkiScapeFarmingBadge"):
                if _FARMING_BADGE is None or child is not _FARMING_BADGE:
                    try:
                        child.hide()
                        child.deleteLater()
                    except Exception:
                        pass
    except Exception:
        pass

def ensure_review_hud() -> None:
    """Create the Review HUD if missing and attach to mw."""
    global _REVIEW_HUD
    try:
        if not HAS_QT:
            return
        # Proactively clean up any leftover HUD windows from previous runs
        _cleanup_extra_huds()
        if _REVIEW_HUD is None:
            parent = mw
            if parent is None:
                return
            _REVIEW_HUD = ReviewHUD(parent)
            try:
                # Ensure correct parenting in case older instances detached
                _REVIEW_HUD.setParent(parent)
            except Exception:
                pass
        # ensure on top and visible (content set by update call)
        try:
            _REVIEW_HUD.raise_()
        except Exception:
            pass
        _raise_exp_popup()
    except Exception:
        pass

def update_review_hud(player_data: dict, current_skill: str) -> None:
    """Update and show the Review HUD based on current data."""
    try:
        if not HAS_QT:
            return
        # Respect setting to fully disable the review HUD visuals
        if not get_config_bool("ankiscape_review_hud_enabled", True):
            try:
                if _REVIEW_HUD is not None and hasattr(_REVIEW_HUD, "hide"):
                    _REVIEW_HUD.hide()
            except Exception:
                pass
            return
        ensure_review_hud()
        if _REVIEW_HUD is not None:
            _REVIEW_HUD.set_data(player_data, current_skill)
    except Exception:
        pass


def ensure_review_context_action_strip() -> None:
    global _REVIEW_CONTEXT_STRIP
    if not HAS_QT:
        return
    _cleanup_extra_huds()
    if _REVIEW_CONTEXT_STRIP is None and mw is not None:
        _REVIEW_CONTEXT_STRIP = ReviewContextActionStrip(mw)
        _REVIEW_CONTEXT_STRIP.setParent(mw)
    if _REVIEW_CONTEXT_STRIP is not None:
        _REVIEW_CONTEXT_STRIP.raise_()
        _raise_exp_popup()


def update_review_context_action_strip(
    player_data: dict,
    action_callback=None,
) -> None:
    if not HAS_QT:
        return
    ensure_review_context_action_strip()
    if _REVIEW_CONTEXT_STRIP is None:
        return
    projection = review_context_projection_pure(player_data)
    if projection.get("active") is None:
        _REVIEW_CONTEXT_STRIP.hide()
        return
    _REVIEW_CONTEXT_STRIP.set_data(projection, action_callback)


def hide_review_context_action_strip() -> None:
    try:
        if _REVIEW_CONTEXT_STRIP is not None:
            _REVIEW_CONTEXT_STRIP.hide()
    except Exception:
        pass


def ensure_farming_hud_badge() -> None:
    global _FARMING_BADGE
    if not HAS_QT:
        return
    _cleanup_extra_huds()
    if _FARMING_BADGE is None and mw is not None:
        _FARMING_BADGE = FarmingHUDBadge(mw)
        _FARMING_BADGE.setParent(mw)
    if _FARMING_BADGE is not None:
        _FARMING_BADGE.raise_()
        _raise_exp_popup()


def update_farming_hud_badge(player_data: dict, open_callback=None) -> None:
    if not HAS_QT or not get_config_bool("ankiscape_review_hud_enabled", True):
        hide_farming_hud_badge()
        return
    ensure_farming_hud_badge()
    if _FARMING_BADGE is not None:
        _FARMING_BADGE.set_data(farming_frontend_projection_pure(player_data), open_callback)


def ensure_distraction_hud_badge() -> None:
    global _DISTRACTION_BADGE
    if not HAS_QT:
        return
    if _DISTRACTION_BADGE is None and mw is not None:
        _DISTRACTION_BADGE = DistractionHUDBadge(mw)
        _DISTRACTION_BADGE.setParent(mw)
    if _DISTRACTION_BADGE is not None:
        _DISTRACTION_BADGE.raise_()
        _raise_exp_popup()


def update_distraction_hud_badge(player_data: dict, open_callback=None) -> None:
    if not HAS_QT or not get_config_bool("ankiscape_review_hud_enabled", True):
        hide_distraction_hud_badge()
        return
    ensure_distraction_hud_badge()
    if _DISTRACTION_BADGE is not None:
        _DISTRACTION_BADGE.set_data(_world_event_rows(player_data), open_callback)


def _position_farming_status_dialog() -> None:
    try:
        if _FARM_STATUS_DIALOG is None or _FARMING_BADGE is None or mw is None:
            return
        frame = _FARM_STATUS_DIALOG
        frame.adjustSize()
        frame.resize(max(360, frame.width()), min(380, max(180, frame.sizeHint().height())))
        x = min(max(8, _FARMING_BADGE.x()), max(8, mw.width() - frame.width() - 8))
        y = _FARMING_BADGE.y() - frame.height() - 8
        if y < 8:
            y = min(mw.height() - frame.height() - 8, _FARMING_BADGE.y() + _FARMING_BADGE.height() + 8)
        frame.move(x, max(8, y))
    except Exception:
        pass


def close_farming_status_dialog() -> None:
    global _FARM_STATUS_DIALOG
    if _FARM_STATUS_DIALOG is not None:
        try:
            _FARM_STATUS_DIALOG.hide()
            _FARM_STATUS_DIALOG.deleteLater()
        except Exception:
            pass
    _FARM_STATUS_DIALOG = None


def show_farming_status_dialog(projection: dict, open_callback=None) -> None:
    global _FARM_STATUS_DIALOG
    if not HAS_QT or mw is None:
        return
    if _FARM_STATUS_DIALOG is not None and _FARM_STATUS_DIALOG.isVisible():
        close_farming_status_dialog()
        return

    class _StatusFrame(QFrame):
        def keyPressEvent(self, event):  # type: ignore[override]
            if event.key() == Qt.Key.Key_Escape:
                close_farming_status_dialog()
                if _FARMING_BADGE is not None:
                    _FARMING_BADGE.setFocus()
                return
            super().keyPressEvent(event)

    frame = _StatusFrame(mw)
    frame.setObjectName("farmingStatusDialog")
    frame.setWindowFlags(Qt.WindowType.Widget)
    frame.setFrameShape(QFrame.Shape.StyledPanel)
    frame.setStyleSheet(
        "QFrame#farmingStatusDialog { background: palette(base); color: palette(text); border: 1px solid palette(mid); border-radius: 10px; }"
    )
    root = QVBoxLayout(frame)
    root.setContentsMargins(12, 10, 12, 10)
    header = QHBoxLayout()
    title = QLabel("Farming")
    title.setStyleSheet("font-weight: 700; color: palette(text);")
    close = QToolButton()
    close.setText("×")
    close.setAccessibleName("Close Farming status")
    close.clicked.connect(close_farming_status_dialog)
    header.addWidget(title)
    header.addStretch(1)
    header.addWidget(close)
    root.addLayout(header)
    rows = QListWidget()
    rows.setObjectName("farmingStatusList")
    rows.setMaximumHeight(220)
    compact_rows = tuple(projection.get("compact_rows", ()))
    if compact_rows:
        for row in compact_rows:
            item = QListWidgetItem(f"{row['crop_name']} · {row['status_label']} · {row['patch_name']}")
            item.setData(Qt.ItemDataRole.UserRole, row["patch_id"])
            rows.addItem(item)
    else:
        item = QListWidgetItem("No crops are growing.")
        item.setFlags(item.flags() & ~Qt.ItemFlag.ItemIsEnabled)
        rows.addItem(item)
    root.addWidget(rows)
    queue = QLabel(f"Queue: {int(projection.get('queued_count', 0) or 0)} steps · next successful reviews")
    queue.setStyleSheet(f"color: {dim_text_css(queue)};")
    root.addWidget(queue)
    footer = QHBoxLayout()
    footer.addStretch(1)
    open_button = QPushButton("Open full farm")
    open_button.setObjectName("farmingOpenFarmButton")

    def _open(patch_id=None):
        close_farming_status_dialog()
        if open_callback is not None:
            open_callback(patch_id)

    open_button.clicked.connect(lambda _=False: _open())
    rows.itemActivated.connect(lambda item: _open(item.data(Qt.ItemDataRole.UserRole)))
    rows.itemDoubleClicked.connect(lambda item: _open(item.data(Qt.ItemDataRole.UserRole)))
    footer.addWidget(open_button)
    root.addLayout(footer)
    _FARM_STATUS_DIALOG = frame
    _position_farming_status_dialog()
    frame.show()
    frame.raise_()
    frame.setFocus()


def hide_farming_hud_badge() -> None:
    close_farming_status_dialog()
    try:
        if _FARMING_BADGE is not None:
            _FARMING_BADGE.hide()
    except Exception:
        pass


def hide_distraction_hud_badge() -> None:
    try:
        if _DISTRACTION_BADGE is not None:
            _DISTRACTION_BADGE.hide()
    except Exception:
        pass


def hide_review_hud() -> None:
    """Hide the HUD and its interactive siblings outside review screens."""
    try:
        if _REVIEW_HUD is not None and hasattr(_REVIEW_HUD, "hide"):
            _REVIEW_HUD.hide()
    except Exception:
        pass
    hide_review_context_action_strip()
    hide_farming_hud_badge()
    hide_distraction_hud_badge()

def show_error_message(title: str, message: str):
    """Centralized error dialog helper."""
    error_dialog = QMessageBox(mw)
    error_dialog.setIcon(QMessageBox.Icon.Warning)
    # Force the standard warning glyph. On macOS QMessageBox otherwise falls back
    # to the host app's icon (the Python/Anki "folder" the user saw) for the body
    # icon, which looks like a bug. The style's SP_MessageBoxWarning is a proper
    # caution triangle on every platform.
    try:
        from aqt.qt import QStyle, QApplication
        style = (mw.style() if mw is not None else None) or QApplication.style()
        warning = style.standardIcon(QStyle.StandardPixmap.SP_MessageBoxWarning)
        pm = warning.pixmap(48, 48)
        if not pm.isNull():
            error_dialog.setIconPixmap(pm)
    except Exception:
        pass
    error_dialog.setWindowTitle(title)
    error_dialog.setText(message)
    error_dialog.setStandardButtons(QMessageBox.StandardButton.Ok)
    error_dialog.exec()


def show_level_up_dialog(skill: str):
    """Level-up dialog with a skill icon."""
    dialog = QDialog(mw)
    dialog.setWindowTitle("Level Up!")
    dialog.setFixedSize(380, 200)
    layout = QVBoxLayout()

    # Icon row (registry-driven so new skills like Fletching show their icon)
    icon_path = skill_icon_path_for(skill)
    if icon_path:
        icon_label = QLabel()
        pixmap = QPixmap(icon_path)
        icon_label.setPixmap(pixmap.scaled(64, 64, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation))
        layout.addWidget(icon_label, alignment=Qt.AlignmentFlag.AlignCenter)

    msg = QLabel(f"Congratulations! You've advanced a {skill} level!")
    msg.setAlignment(Qt.AlignmentFlag.AlignCenter)
    layout.addWidget(msg)

    ok_button = QPushButton("OK")
    ok_button.clicked.connect(dialog.accept)
    layout.addWidget(ok_button, alignment=Qt.AlignmentFlag.AlignCenter)

    dialog.setLayout(layout)
    dialog.exec()


def show_achievement_dialog(achievement: str, data: dict):
    """Achievement dialog with an icon."""
    dialog = QDialog(mw)
    dialog.setWindowTitle("Achievement Unlocked!")
    dialog.setFixedSize(420, 240)
    layout = QVBoxLayout()

    # Try a specific icon based on achievement name, otherwise use generic
    icon_path = os.path.join(current_dir, "icon", f"{achievement.lower().replace(' ', '_')}.png")
    if not os.path.exists(icon_path):
        icon_path = os.path.join(current_dir, "icon", "achievement_icon.png")
    if os.path.exists(icon_path):
        icon_label = QLabel()
        pixmap = QPixmap(icon_path)
        icon_label.setPixmap(pixmap.scaled(56, 56, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation))
        layout.addWidget(icon_label, alignment=Qt.AlignmentFlag.AlignCenter)

    title = QLabel(achievement)
    title.setAlignment(Qt.AlignmentFlag.AlignCenter)
    title.setStyleSheet("font-size: 16px; font-weight: bold;")
    layout.addWidget(title)

    desc = QLabel(data.get("description", ""))
    desc.setWordWrap(True)
    layout.addWidget(desc, alignment=Qt.AlignmentFlag.AlignCenter)

    ok_button = QPushButton("OK")
    ok_button.clicked.connect(dialog.accept)
    layout.addWidget(ok_button, alignment=Qt.AlignmentFlag.AlignCenter)

    dialog.setLayout(layout)
    dialog.exec()


def show_stronghold_reward_dialog() -> Optional[str]:
    """Boot-choice reward for clearing the Stronghold of Security. Both pairs are
    stat-identical, so the copy makes clear the pick is purely cosmetic. Returns
    the chosen boot name, or None if the player dismissed the dialog unclaimed."""
    dialog = QDialog(mw)
    dialog.setWindowTitle("Stronghold of Security — Cleared!")
    dialog.setMinimumWidth(440)
    layout = QVBoxLayout()

    title = QLabel("You escaped the Stronghold of Security!")
    title.setAlignment(Qt.AlignmentFlag.AlignCenter)
    title.setStyleSheet("font-size: 16px; font-weight: bold;")
    layout.addWidget(title)

    body = QLabel(
        f"Claim your reward: {STRONGHOLD_REWARD_COINS:,} coins and a pair of boots. "
        "Both pairs share the same stats, so choose whichever look you prefer."
    )
    body.setWordWrap(True)
    body.setAlignment(Qt.AlignmentFlag.AlignCenter)
    layout.addWidget(body)

    chosen = {"boots": None}
    button_row = QHBoxLayout()
    for boots in STRONGHOLD_BOOT_CHOICES:
        btn = QPushButton(boots)

        def _pick(_checked=False, name=boots):
            chosen["boots"] = name
            dialog.accept()

        btn.clicked.connect(_pick)
        button_row.addWidget(btn)
    layout.addLayout(button_row)

    dialog.setLayout(layout)
    dialog.exec()
    return chosen["boots"]


def create_menu(on_main_menu):
    """Create a single AnkiScape > Menu entry that opens the consolidated window."""
    previous = getattr(mw, "_ankiscape_menu", None)
    if previous is not None:
        try:
            mw.form.menubar.removeAction(previous.menuAction())
            previous.deleteLater()
        except RuntimeError:
            pass
    menu = QMenu("AnkiScape", mw)
    mw._ankiscape_menu = menu
    mw.form.menubar.addMenu(menu)
    main_action = menu.addAction("Menu")
    main_action.triggered.connect(lambda _checked=False: on_main_menu())
    return menu


def update_menu_visibility(current_skill: str):
    """No-op: single consolidated menu item is always visible."""
    return


def _combat_loadout_summary_text(player_data: dict) -> str:
    summary = combat_supply_loadout_summary_pure(player_data)

    def _mapping_text(mapping: object) -> str:
        if not isinstance(mapping, dict) or not mapping:
            return "none loaded"
        return ", ".join(f"{item} x{amount}" for item, amount in mapping.items())

    return (
        f"Food: {summary.get('food_loaded', 0)} loaded\n"
        f"Potions: {_mapping_text(summary.get('potions_loaded_items'))}\n"
        f"Stat potions: {_mapping_text(summary.get('stat_potions_loaded_items'))}\n"
        f"Ammo: {_mapping_text(summary.get('ammo_loaded'))}\n"
        f"Runes: {_mapping_text(summary.get('runes_loaded'))}\n"
        f"Finishers: {_mapping_text(summary.get('finishers_loaded'))}\n"
        f"Hazard supplies: {_mapping_text(summary.get('hazards_loaded'))}"
    )


def _help_registry_tables() -> dict[str, HelpRegistryTable]:
    """Build volatile Help reference rows from their owning live registries."""

    skills = sorted(
        implemented_skill_definitions(),
        key=lambda skill: (skill.category, skill.display_name.casefold()),
    )
    return {
        "implemented_skills": HelpRegistryTable(
            headers=("Skill", "Group"),
            rows=tuple(
                (skill.display_name, skill.category.title()) for skill in skills
            ),
        )
    }


