    def _build_hunter_list() -> QWidget:
        panel = QWidget()
        panel.setObjectName("hunterSkillPanel")
        panel_layout = QVBoxLayout(panel)
        panel_layout.setContentsMargins(0, 0, 0, 0)
        panel_layout.setSpacing(8)

        private_ground = QCheckBox()
        private_ground.setObjectName("hunterPrivateGroundCheck")
        private_ground.setStyleSheet("color: palette(text);")
        private_ground.setToolTip(
            "Use one carried quota ticket only after a successful ordinary "
            "catch. Failed catches preserve the ticket."
        )
        private_hint = QLabel()
        private_hint.setObjectName("hunterPrivateGroundHint")
        private_hint.setWordWrap(True)
        private_hint.setStyleSheet(
            f"color: {dim_text_css(private_hint)}; font-size: 11px;"
        )

        def _carried_inventory_for_target(target_id: str) -> Mapping[str, Any]:
            carried = player_data.get("carried_inventory")
            if isinstance(carried, Mapping) and target_id in carried:
                value = carried.get(target_id)
                return value if isinstance(value, Mapping) else {}
            advanced = bool(
                (player_data.get("carried_advanced_targets") or {}).get(
                    target_id, False
                )
            )
            if advanced:
                layouts = player_data.get("carried_layout") or {}
                value = layouts.get(target_id) if isinstance(layouts, Mapping) else {}
                return value if isinstance(value, Mapping) else {}
            return {}

        def _refresh_private_ground() -> None:
            target_id = str(
                player_data.get("current_hunter", DEFAULT_HUNTER_TARGET)
            )
            status = hunter_private_ground_status_pure(
                player_data,
                target_id,
                inventory_override=_carried_inventory_for_target(target_id),
            )
            private_ground.blockSignals(True)
            private_ground.setChecked(bool(status["configured"]))
            private_ground.blockSignals(False)
            private_ground.setVisible(bool(status["available"]))
            private_hint.setVisible(bool(status["available"]))
            if not status["available"]:
                return
            ticket_name = str(status["ticket"])
            ticket_count = int(status["tickets"])
            private_ground.setText(f"Use private hunting ground · {ticket_count} carried")
            private_ground.setEnabled(
                on_big_chinchompa_command is not None
                and (ticket_count > 0 or bool(status["configured"]))
            )
            if ticket_count > 0:
                private_hint.setText(
                    f"{ticket_name} is consumed only after a successful catch."
                )
            else:
                private_hint.setText(
                    f"Add {ticket_name} to this target's Bank carried pack."
                )

        def _set_hunter_target(target_id: str) -> None:
            if on_set_hunter is not None:
                on_set_hunter(target_id)
            player_data["current_hunter"] = target_id
            _refresh_private_ground()

        tree = _build_grouped_target_tree(
            hunter_target_rows(
                player_data,
                HUNTER_DATA,
                HUNTER_ITEM_IMAGES,
                DEFAULT_HUNTER_TARGET,
                QUEST_UNLOCK_RULES,
            ),
            HUNTER_GROUP_LABELS,
            "__hunter_group__:",
            _set_hunter_target,
            group_order=list(HUNTER_GROUP_ORDER),
        )
        tree.setObjectName("hunterTargetTree")
        panel_layout.addWidget(tree, 1)
        panel_layout.addWidget(private_ground)
        panel_layout.addWidget(private_hint)

        def _toggle_private_ground(enabled: bool) -> None:
            if on_big_chinchompa_command is None:
                return
            target_id = str(
                player_data.get("current_hunter", DEFAULT_HUNTER_TARGET)
            )
            result = on_big_chinchompa_command(
                "set_private_ground",
                {"target_id": target_id, "enabled": bool(enabled)},
            )
            if not result.get("ok", False):
                show_error_message(
                    "Private hunting ground",
                    str(result.get("message", "Could not update private hunting ground.")),
                )
            _refresh_private_ground()

        private_ground.toggled.connect(_toggle_private_ground)
        _refresh_private_ground()
        return panel

    def _build_cooking_list() -> QTreeWidget:
        images = dict(COOKING_ITEM_IMAGES)
        images.update(_item_asset_paths())
        return _build_grouped_target_tree(
            cooking_target_rows(
                player_data,
                COOKING_DATA,
                images,
                DEFAULT_COOKING_TARGET,
                QUEST_UNLOCK_RULES,
            ),
            _COOKING_FAMILY_LABELS,
            "__cooking_family__:",
            on_set_cooking,
        )

    wicked_hood_feedback = {"message": ""}

    def _build_runecrafting_list() -> QWidget:
        panel = QWidget()
        panel.setObjectName("runecraftingSkillPanel")
        layout = QVBoxLayout(panel)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(8)

        hood = wicked_hood_view_pure(player_data)
        hood_card = QtFrame()
        hood_card.setObjectName("wickedHoodCard")
        hood_card.setVisible(bool(hood["owned"] or hood["claimed"]))
        hood_card.setStyleSheet(
            "QFrame#wickedHoodCard { border: 1px solid palette(mid); border-radius: 8px;"
            " background: palette(base); }"
        )
        hood_layout = QVBoxLayout(hood_card)
        hood_layout.setContentsMargins(10, 8, 10, 8)
        hood_layout.setSpacing(6)

        header = QHBoxLayout()
        hood_icon_path = RUNECRAFTING_ITEM_IMAGES.get("Wicked hood")
        if hood_icon_path:
            hood_icon = QLabel()
            hood_icon.setObjectName("wickedHoodIcon")
            hood_icon.setFixedSize(28, 28)
            pixmap = QPixmap(hood_icon_path)
            if not pixmap.isNull():
                hood_icon.setPixmap(
                    pixmap.scaled(
                        28,
                        28,
                        Qt.AspectRatioMode.KeepAspectRatio,
                        Qt.TransformationMode.FastTransformation,
                    )
                )
            header.addWidget(hood_icon)
        title = QLabel("Wicked hood")
        title.setObjectName("wickedHoodTitle")
        title.setStyleSheet("color: palette(text); font-weight: 700;")
        header.addWidget(title)
        header.addStretch(1)
        hood_layout.addLayout(header)

        remaining = QLabel(
            f"{hood['essence_remaining']}/{hood['caps']['essence']} essence · "
            f"{hood['rune_withdrawals_remaining']}/{hood['caps']['runes']} rune withdrawals · "
            f"{hood['teleports_remaining']}/{hood['caps']['teleports']} teleports"
        )
        remaining.setObjectName("wickedHoodRemainingLabel")
        remaining.setWordWrap(True)
        remaining.setStyleSheet(
            f"color: {dim_text_css(remaining)}; font-size: 11px; font-weight: 700;"
        )
        hood_layout.addWidget(remaining)

        pending_altar = str(hood.get("pending_altar_teleport", "") or "")
        pending_option = next(
            (
                option
                for option in hood["altar_options"]
                if option["altar_id"] == pending_altar
            ),
            None,
        )
        allowances_exhausted = not any(
            int(hood[key]) > 0
            for key in (
                "essence_remaining",
                "rune_withdrawals_remaining",
                "teleports_remaining",
            )
        )
        if hood["claimed"] and not hood["owned"]:
            guidance_text = "Reclaim the hood to restore its saved upgrades and allowances."
        elif not hood["operable"]:
            guidance_text = "Equip the hood or place it in this target's carried pack."
        elif pending_option:
            guidance_text = (
                f"Queued for {pending_option['display_name']} · "
                "the next matching outbound route is skipped"
            )
        elif allowances_exhausted:
            guidance_text = "Allowances exhausted · refills every 240 answered cards"
        else:
            guidance_text = (
                f"Ready · dispenses {hood['essence_item']} · "
                "refills every 240 answered cards"
            )
        guidance = QLabel(guidance_text)
        guidance.setObjectName("wickedHoodGuidanceLabel")
        guidance.setWordWrap(True)
        guidance.setStyleSheet(
            f"color: {dim_text_css(guidance)}; font-size: 11px;"
        )
        hood_layout.addWidget(guidance)

        feedback = QLabel(wicked_hood_feedback["message"])
        feedback.setObjectName("wickedHoodFeedbackLabel")
        feedback.setWordWrap(True)
        feedback.setStyleSheet("color: palette(text);")
        feedback.setVisible(bool(wicked_hood_feedback["message"]))
        hood_layout.addWidget(feedback)

        controls = QGridLayout()
        controls.setSpacing(6)
        essence_button = QPushButton("Withdraw essence")
        essence_button.setObjectName("wickedHoodEssenceButton")
        essence_button.setAccessibleName("Withdraw Wicked hood essence")
        essence_button.setToolTip(
            "Fill free carried-pack slots from the remaining essence allowance."
        )
        essence_button.setEnabled(
            on_wicked_hood_command is not None
            and bool(hood["operable"])
            and int(hood["essence_remaining"]) > 0
        )
        controls.addWidget(essence_button, 0, 0, 1, 2)

        altar_options = tuple(hood["altar_options"])
        rune_choice = QComboBox()
        rune_choice.setObjectName("wickedHoodRuneCombo")
        rune_choice.setAccessibleName("Wicked hood rune choice")
        rune_choice.setSizeAdjustPolicy(
            QComboBox.SizeAdjustPolicy.AdjustToMinimumContentsLengthWithIcon
        )
        rune_choice.setMinimumContentsLength(14)
        rune_choice.setToolTip("Choose a fed altar's rune for the next withdrawal.")
        teleport_choice = QComboBox()
        teleport_choice.setObjectName("wickedHoodTeleportCombo")
        teleport_choice.setAccessibleName("Wicked hood altar teleport choice")
        teleport_choice.setSizeAdjustPolicy(
            QComboBox.SizeAdjustPolicy.AdjustToMinimumContentsLengthWithIcon
        )
        teleport_choice.setMinimumContentsLength(14)
        for option in altar_options:
            rune_choice.addItem(
                f"{option['rune_item']} ×{option['rune_quantity']}", option["altar_id"]
            )
            teleport_choice.addItem(
                option["display_name"]
                if option["level_met"]
                else f"{option['display_name']} (Lv {option['level']})",
                option["altar_id"],
            )
        if not altar_options:
            rune_choice.addItem("No altars fed", "")
            teleport_choice.addItem("No altars fed", "")
        elif pending_altar:
            pending_index = teleport_choice.findData(pending_altar)
            if pending_index >= 0:
                teleport_choice.setCurrentIndex(pending_index)
        rune_choice.setEnabled(bool(altar_options) and bool(hood["operable"]))
        teleport_choice.setEnabled(
            bool(altar_options) and bool(hood["operable"]) and not pending_altar
        )
        controls.addWidget(rune_choice, 1, 0)
        rune_button = QPushButton("Withdraw")
        rune_button.setObjectName("wickedHoodRunesButton")
        rune_button.setAccessibleName("Withdraw Wicked hood runes")
        rune_button.setToolTip(
            "Spend one withdrawal: 100 free-to-play runes or 5 members' runes."
        )
        rune_button.setEnabled(
            on_wicked_hood_command is not None
            and bool(hood["operable"])
            and bool(altar_options)
            and int(hood["rune_withdrawals_remaining"]) > 0
        )
        controls.addWidget(rune_button, 1, 1)
        controls.addWidget(teleport_choice, 2, 0)
        teleport_button = QPushButton("Teleport")
        teleport_button.setObjectName("wickedHoodTeleportButton")
        teleport_button.setAccessibleName("Use Wicked hood altar teleport")

        def _refresh_teleport_gate() -> None:
            altar_id = str(teleport_choice.currentData() or "")
            selected = next(
                (option for option in altar_options if option["altar_id"] == altar_id),
                None,
            )
            level_met = bool(selected and selected["level_met"])
            teleport_button.setEnabled(
                on_wicked_hood_command is not None
                and bool(hood["operable"])
                and level_met
                and int(hood["teleports_remaining"]) > 0
                and not pending_altar
            )
            if selected and not level_met:
                teleport_button.setToolTip(
                    f"Requires level {selected['level']} Runecrafting."
                )
            elif not altar_options:
                teleport_button.setToolTip("Feed a talisman or tiara to unlock an altar.")
            else:
                teleport_button.setToolTip(
                    "Spend one teleport to skip the selected altar route's outbound leg."
                )

        _refresh_teleport_gate()
        teleport_choice.currentIndexChanged.connect(
            lambda _index: _refresh_teleport_gate()
        )
        controls.addWidget(teleport_button, 2, 1)

        claimed = bool(hood["claimed"])
        owns_hood = bool(hood["owned"])
        reclaim_button = QPushButton("Reclaim")
        reclaim_button.setObjectName("wickedHoodReclaimButton")
        reclaim_button.setAccessibleName("Reclaim Wicked hood")
        reclaim_button.setToolTip(
            "Restore the one Wicked hood without resetting its saved progress."
        )
        reclaim_button.setVisible(claimed and not owns_hood)
        reclaim_button.setEnabled(on_wicked_hood_command is not None and claimed and not owns_hood)
        controls.addWidget(reclaim_button, 3, 0, 1, 2)
        hood_layout.addLayout(controls)

        def _run_hood_action(action_id: str, payload: dict | None = None) -> None:
            if on_wicked_hood_command is None:
                return
            result = on_wicked_hood_command(action_id, payload or {}) or {}
            wicked_hood_feedback["message"] = str(
                result.get("message", "" if result.get("ok") else "That action is unavailable.")
            )
            _render_panel()

        essence_button.clicked.connect(lambda _checked=False: _run_hood_action("essence"))
        rune_button.clicked.connect(
            lambda _checked=False: _run_hood_action(
                "runes", {"altar_id": str(rune_choice.currentData() or "")}
            )
        )
        teleport_button.clicked.connect(
            lambda _checked=False: _run_hood_action(
                "teleport", {"altar_id": str(teleport_choice.currentData() or "")}
            )
        )
        reclaim_button.clicked.connect(lambda _checked=False: _run_hood_action("reclaim"))
        layout.addWidget(hood_card)

        tree = _build_grouped_target_tree(
            runecrafting_target_rows(
                player_data,
                RUNECRAFTING_DATA,
                RUNECRAFTING_ITEM_IMAGES,
                RUNECRAFTING_POUCH_DATA,
                DEFAULT_RUNECRAFTING_TARGET,
                QUEST_UNLOCK_RULES,
            ),
            RUNECRAFTING_GROUP_LABELS,
            "__runecrafting_group__:",
            on_set_runecrafting,
            group_order=list(RUNECRAFTING_GROUP_LABELS),
        )
        tree.setObjectName("runecraftingTargetTree")
        layout.addWidget(tree, 1)
        return panel

    def _build_thieving_list() -> QWidget:
        panel = QWidget()
        panel.setObjectName("thievingSkillPanel")
        layout = QVBoxLayout(panel)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(8)

        casual_row = QWidget()
        casual_row.setObjectName("thievingCasualControls")
        casual_layout = QHBoxLayout(casual_row)
        casual_layout.setContentsMargins(0, 0, 0, 0)
        casual_layout.setSpacing(8)
        casual_label = QLabel("Casual")
        casual_label.setStyleSheet("color: palette(text); font-weight: 600;")
        fight_back = QCheckBox("Fight back when caught")
        fight_back.setObjectName("thievingFightBackCheck")
        fight_back.setChecked(bool(player_data.get("thieving_fight_back_when_caught", False)))
        fight_back.setToolTip(
            "Off: flee after the sourced damage. On: enter a real combat encounter "
            "when a stall guard or blackjack thug catches you."
        )
        if on_set_thieving_fight_back is not None:
            fight_back.toggled.connect(
                lambda enabled: on_set_thieving_fight_back(bool(enabled))
            )
        casual_layout.addWidget(casual_label)
        casual_layout.addWidget(fight_back)
        casual_layout.addStretch(1)
        layout.addWidget(casual_row)

        def _select_thieving_target(target_id: str) -> None:
            if on_set_thieving is not None:
                on_set_thieving(target_id)
                _render_panel()

        tree = _build_grouped_target_tree(
            thieving_target_rows(
                player_data,
                THIEVING_TARGETS,
                THIEVING_ITEM_IMAGES,
                DEFAULT_THIEVING_TARGET,
            ),
            dict(THIEVING_GROUP_LABELS),
            "__thieving_group__:",
            _select_thieving_target,
            group_order=list(THIEVING_GROUP_ORDER),
        )
        tree.setObjectName("thievingTargetTree")
        layout.addWidget(tree, 1)
        return panel

    agility_feedback = {"message": ""}

    def _build_agility_list() -> QWidget:
        panel = QWidget()
        panel.setObjectName("agilitySkillPanel")
        layout = QVBoxLayout(panel)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(8)

        status = QLabel(agility_status_line_pure(player_data))
        status.setObjectName("agilityStatusLine")
        status.setWordWrap(True)
        status.setStyleSheet("color: palette(text); font-weight: 600;")
        layout.addWidget(status)

        pit_auto_accept = QCheckBox(
            "Automatically accept Talent Scout invitations"
        )
        pit_auto_accept.setObjectName("agilityPitAutoAcceptCheckBox")
        pit_auto_accept.setChecked(
            bool(player_data.get("agility_pit_auto_accept", True))
        )
        pit_auto_accept.setToolTip(
            "Eligible completed course laps may immediately enter The Pit. "
            "An active familiar still requires confirmation."
        )

        def _set_pit_auto_accept(enabled: bool) -> None:
            if on_agility_command is None:
                return
            result = on_agility_command(
                "set_pit_auto_accept",
                {"enabled": bool(enabled)},
            ) or {}
            if not result.get("ok", result.get("allowed", False)):
                pit_auto_accept.blockSignals(True)
                pit_auto_accept.setChecked(not enabled)
                pit_auto_accept.blockSignals(False)

        pit_auto_accept.toggled.connect(_set_pit_auto_accept)
        layout.addWidget(pit_auto_accept)

        level = max(1, min(99, int(player_data.get("agility_level", 1) or 1)))
        gain = 11.0 * (level - 1) / 98.0
        equipment = set((player_data.get("equipment") or {}).values())
        reduction = sum(
            value for item, value in {
                "Agile top": 12.0,
                "Agile legs": 10.0,
                "Boots of lightness": 4.5,
                "Spotted cape": 2.2,
                "Spottier cape": 4.5,
            }.items() if item in equipment
        )
        counts = player_data.get("agility_lap_counts") or {}
        travel = player_data.get("agility_last_travel") or {}
        base_reviews = float(travel.get("base_reviews", 0.0) or 0.0)
        adjusted_reviews = float(travel.get("adjusted_reviews", base_reviews) or base_reviews)
        route_gain = 100.0 * max(0.0, base_reviews - adjusted_reviews) / base_reviews if base_reviews > 0 else 0.0
        unlocked_routes = sum(1 for row in ALL_AGILITY_SHORTCUTS if row.consumer == "route" and row.level <= level)
        next_shortcut = next((row for row in sorted(ALL_AGILITY_SHORTCUTS, key=lambda item: item.level) if row.level > level), None)
        next_shortcut_text = (
            f"next: {next_shortcut.display_name} at {next_shortcut.level} · "
            if next_shortcut
            else "all milestones unlocked · "
        )
        travel_summary = (
            f"last route {travel.get('route_label', 'travel')} saved {route_gain:.1f}% · "
            f"effective load {float(travel.get('effective_weight_kg', 0.0) or 0.0):g} kg"
            if travel else f"up to {gain:.1f}% less travel cost on movement-heavy routes"
        )
        benefits = QLabel(
            f"Benefits & shortcuts · {travel_summary} · equipped reduction {reduction:g} kg · "
            f"{unlocked_routes} consuming routes unlocked · {next_shortcut_text}"
            f"{int(counts.get('total', 0) or 0)} laps"
        )
        benefits.setObjectName("agilityBenefitsLine")
        benefits.setWordWrap(True)
        benefits.setStyleSheet("color: palette(text); font-size: 11px;")
        benefits.setToolTip(
            "Agility affects only route-local travel reviews. Bank transactions, materials, XP, and stationary methods are unchanged."
        )
        layout.addWidget(benefits)

        def _accept_pit_offer() -> bool:
            if on_agility_command is None:
                return False
            result = on_agility_command("accept_pit_offer", {}) or {}
            if result.get("requires_familiar_dismissal"):
                answer = QMessageBox.question(
                    panel,
                    "Dismiss familiar and enter The Pit?",
                    "The Talent Scout does not allow familiars. Dismissing it "
                    "does not refund its pouch, and any stored cargo is dropped "
                    "for the normal reclaim window. Continue?",
                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                    QMessageBox.StandardButton.No,
                )
                if answer != QMessageBox.StandardButton.Yes:
                    return False
                result = on_agility_command(
                    "accept_pit_offer",
                    {"dismiss_familiar": True},
                ) or {}
            if not result.get("ok", result.get("allowed", False)):
                agility_feedback["message"] = str(
                    result.get("message", "Could not enter The Pit")
                )
                return False
            agility_feedback["message"] = str(result.get("message", ""))
            return True

        if bool(player_data.get("agility_pit_offer", False)):
            invitation = QWidget()
            invitation.setObjectName("agilityPitInvitationRow")
            invitation.setStyleSheet(
                "QWidget#agilityPitInvitationRow {"
                " background: palette(base);"
                " border: 1px solid rgba(76,175,80,0.65);"
                " border-radius: 8px;"
                " }"
            )
            invitation_layout = QHBoxLayout(invitation)
            invitation_layout.setContentsMargins(8, 6, 8, 6)
            origin = str(
                player_data.get("agility_pit_origin_course", "") or ""
            )
            origin_spec = AGILITY_TARGETS_BY_ID.get(origin)
            invitation_label = QLabel(
                "Talent Scout invitation"
                + (
                    f" · {origin_spec.display_name}"
                    if origin_spec is not None
                    else ""
                )
            )
            invitation_label.setStyleSheet(
                "color: palette(text); font-weight: 600;"
            )
            invitation_layout.addWidget(invitation_label)
            invitation_layout.addStretch(1)
            accept_invitation = QPushButton("Accept")
            accept_invitation.setObjectName("agilityPitAcceptButton")
            accept_invitation.setDefault(True)
            accept_invitation.setStyleSheet(
                "QPushButton {"
                " background: rgba(76,175,80,0.22);"
                " border: 1px solid rgba(76,175,80,0.72);"
                " border-radius: 4px;"
                " padding: 4px 12px;"
                " }"
                "QPushButton:hover { background: rgba(76,175,80,0.32); }"
            )
            decline_invitation = QPushButton("Decline")
            decline_invitation.setObjectName("agilityPitDeclineButton")
            def _accept_pending_pit_offer(_checked=False) -> None:
                _accept_pit_offer()
                _render_panel()

            accept_invitation.clicked.connect(_accept_pending_pit_offer)

            def _decline_pit_offer(_checked=False) -> None:
                if on_agility_command is not None:
                    on_agility_command("decline_pit_offer", {})
                _render_panel()

            decline_invitation.clicked.connect(_decline_pit_offer)
            invitation_layout.addWidget(accept_invitation)
            invitation_layout.addWidget(decline_invitation)
            layout.insertWidget(1, invitation)

        def _select_agility_target(target_id: str) -> None:
            current = str(player_data.get("current_agility", DEFAULT_AGILITY_TARGET))
            if current == "brimhaven_arena" and target_id != current and on_agility_command is not None:
                result = on_agility_command("abandon", {}) or {}
                if not result.get("ok", result.get("allowed", False)):
                    agility_feedback["message"] = str(
                        result.get("message", "Could not end the Brimhaven stint")
                    )
                    _render_panel()
                    return
            if target_id == "the_pit" and bool(
                player_data.get("agility_pit_offer", False)
            ):
                _accept_pit_offer()
                _render_panel()
                return
            if on_set_agility is not None:
                on_set_agility(target_id)
            _render_panel()

        tree = _build_grouped_target_tree(
            agility_target_rows(
                player_data,
                AGILITY_TARGETS,
                AGILITY_TARGET_IMAGES,
                DEFAULT_AGILITY_TARGET,
            ),
            dict(AGILITY_GROUP_LABELS),
            "__agility_group__:",
            _select_agility_target,
            group_order=list(AGILITY_GROUP_ORDER),
        )
        tree.setObjectName("agilityTargetTree")
        layout.addWidget(tree, 1)

        rewards = QWidget()
        rewards.setObjectName("agilityRewardControls")
        reward_layout = QGridLayout(rewards)
        reward_layout.setContentsMargins(0, 0, 0, 0)
        reward_layout.setSpacing(6)

        command_index = 0

        command_status = QLabel(agility_feedback["message"])
        command_status.setObjectName("agilityCommandStatus")
        command_status.setWordWrap(True)
        command_status.setVisible(bool(agility_feedback["message"]))
        layout.addWidget(command_status)

        def _run_agility_command(action_id: str, payload: dict) -> None:
            result = on_agility_command(action_id, payload) if on_agility_command is not None else {}
            result = result or {}
            agility_feedback["message"] = str(result.get("message", ""))
            _render_panel()

        def _command_button(label: str, action_id: str, payload=None) -> None:
            nonlocal command_index
            button = QPushButton(label)
            button.setObjectName("agilityCommand::" + action_id)
            button.setEnabled(on_agility_command is not None)
            button.clicked.connect(
                lambda _=False, aid=action_id, body=dict(payload or {}): _run_agility_command(aid, body)
            )
            reward_layout.addWidget(button, command_index // 5, command_index % 5)
            command_index += 1

        _command_button("Sell Pyramid top", "sell_pyramid_top", {"count": 1})
        _command_button("Claim Agile top", "claim_agile_piece", {"piece": "Agile top"})
        _command_button("Claim Agile legs", "claim_agile_piece", {"piece": "Agile legs"})
        for tickets in (1, 10, 25, 100, 1000):
            suffix = "ticket" if tickets == 1 else "tickets"
            _command_button(
                f"Redeem {tickets} {suffix}",
                "redeem_brimhaven_xp",
                {"tickets": tickets},
            )
        _command_button("Toadflax (3 tickets)", "redeem_brimhaven_item", {"tickets": 3})
        _command_button("Wergali (5 tickets)", "redeem_brimhaven_item", {"tickets": 5})
        _command_button("Snapdragon (10)", "redeem_brimhaven_item", {"tickets": 10})
        _command_button("Pirate's hook (800)", "redeem_brimhaven_item", {"tickets": 800})
        _command_button("Activate Surefooted", "activate_surefooted", {})
        _command_button("Wind Toy mouse", "wind_toy_mouse", {})
        _command_button("Buy Agility cape", "purchase_agility_cape", {})
        _command_button("Leave activity", "abandon", {})
        reward_layout.setColumnStretch(4, 1)
        layout.addWidget(rewards)
        return panel

    def _combat_mode_text() -> str:
        style_id = combat_attack_style_for_equipment_pure(player_data, EQUIPMENT_ITEM_DATA)
        spec = COMBAT_ATTACK_STYLE_DATA.get(style_id, COMBAT_ATTACK_STYLE_DATA.get(DEFAULT_COMBAT_ATTACK_STYLE, {}))
        return str(spec.get("display_name", style_id)).replace("Ranged ", "Ranged ").title()

    def _combat_bank_run_text() -> str:
        bank_run_raw = player_data.get("combat_bank_run", {}) or {}
        bank_run_remaining = 0
        if isinstance(bank_run_raw, dict):
            try:
                bank_run_remaining = max(0, int(bank_run_raw.get("reviews_remaining", 0) or 0))
            except (TypeError, ValueError):
                bank_run_remaining = 0
        return (
            f"Bank run: {bank_run_remaining} review{'s' if bank_run_remaining != 1 else ''} remaining"
            if bank_run_remaining
            else "Bank run: ready"
        )

    _combat_setup_refreshers: list = []

    def _build_combat_setup_panel() -> QWidget:
        panel = QWidget()
        layout = QVBoxLayout(panel)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(8)

        mode_label = QLabel(f"Combat mode: {_combat_mode_text()}")
        mode_label.setObjectName("combatModeLabel")
        mode_label.setStyleSheet("color: palette(text); font-weight: 600;")
        layout.addWidget(mode_label)

        action_row = QWidget()
        action_row_layout = QHBoxLayout(action_row)
        action_row_layout.setContentsMargins(0, 0, 0, 0)
        action_row_layout.setSpacing(8)
        action_row_layout.addWidget(QLabel("Next review"))
        action_combo = QComboBox()
        action_combo.setObjectName("combatActionCombo")
        action_row_layout.addWidget(action_combo, 1)
        layout.addWidget(action_row)

        def _refresh_combat_action() -> None:
            target_id = str(
                player_data.get("current_combat_target", DEFAULT_COMBAT_TARGET)
            )
            state = combat_finisher_state_pure(player_data, target_id)
            action_combo.blockSignals(True)
            action_combo.clear()
            action_combo.addItem("Attack", "attack")
            if state["required"]:
                action_combo.addItem(state["action_label"], "finisher")
                finisher_item = action_combo.model().item(1)
                finisher_item.setEnabled(bool(state["available"]))
                if state["available"]:
                    if state.get("charged"):
                        finisher_item.setToolTip(
                            "Spends one Fungicide spray charge and preserves the "
                            "remaining dose. A loaded Fungicide canister automatically "
                            "refills an empty spray."
                        )
                    else:
                        verb = "Consumes one" if state["consumable"] else "Uses the reusable"
                        finisher_item.setToolTip(
                            f"{verb} {state['item']} and finishes the enemy."
                        )
                elif state["ready"]:
                    finisher_item.setToolTip(
                        f"No {state['item']} is loaded in the combat pack."
                    )
                else:
                    finisher_item.setToolTip(
                        f"Available at 1–{state['threshold_lifepoints']} enemy LP."
                    )
                if (
                    player_data.get("combat_action") == "finisher"
                    and state["available"]
                ):
                    action_combo.setCurrentIndex(1)
            action_combo.blockSignals(False)
            action_row.setVisible(bool(state["required"]))

        if on_set_combat_action is not None:
            action_combo.currentIndexChanged.connect(
                lambda _index: on_set_combat_action(
                    str(action_combo.currentData() or "attack")
                )
            )
        _refresh_combat_action()

        # Attack-style picker. The valid styles depend on the equipped weapon's
        # combat class (melee/ranged); a magic weapon has a single fixed style, so
        # the combo is omitted and the mode label above already reads "Magic".
        # The combo is rebuilt on refresh so swapping weapons re-scopes the options.
        style_row = QWidget()
        style_row_layout = QHBoxLayout(style_row)
        style_row_layout.setContentsMargins(0, 0, 0, 0)
        style_row_layout.setSpacing(8)
        style_label = QLabel("Attack style")
        style_label.setStyleSheet("color: palette(text);")
        style_row_layout.addWidget(style_label)
        layout.addWidget(style_row)
        _style_combo_ref = {"combo": None}

        def _rebuild_style_combo() -> None:
            # D2: the options are the equipped weapon's actual AttackStyleData slots,
            # each labeled with its attack type (stab/slash/crush). Selecting a row
            # stores both the weapon_style and the style_type, so parity keys off the
            # exact slot the player picked.
            options = combat_weapon_style_options_pure(player_data, EQUIPMENT_ITEM_DATA)
            old = _style_combo_ref["combo"]
            if old is not None:
                old.setParent(None)
                old.deleteLater()
                _style_combo_ref["combo"] = None
            if len(options) <= 1:
                # Magic (single fixed style) — no selector needed.
                style_row.setVisible(False)
                return
            combo = QComboBox()
            combo.setObjectName("combatStyleCombo")
            current_index = 0
            for index, option in enumerate(options):
                # Spell out which skills each slot trains, so the choice of XP is
                # visible at the point of selection (e.g. "Aggressive (Crush) —
                # Attack + Strength + Defence + Constitution" for the 2h shared slot).
                trains = " + ".join(option["trained_skills"])
                combo.addItem(
                    f"{option['display_name']} — {trains}",
                    (option["weapon_style"], option["style_type"]),
                )
                if option["is_current"]:
                    current_index = index
            combo.setCurrentIndex(current_index)
            if on_set_combat_style is not None:
                combo.currentIndexChanged.connect(
                    lambda _index, c=combo: on_set_combat_style(c.currentData())
                )
            style_row_layout.addWidget(combo, 1)
            _style_combo_ref["combo"] = combo
            style_row.setVisible(True)

        _rebuild_style_combo()

        spell_row = QWidget()
        spell_layout = QHBoxLayout(spell_row)
        spell_layout.setContentsMargins(0, 0, 0, 0)
        spell_layout.setSpacing(8)
        spell_label = QLabel("Autocast")
        spell_label.setStyleSheet("color: palette(text);")
        spell_combo = QComboBox()
        spell_combo.setObjectName("combatSpellCombo")
        current_spell = player_data.get("current_combat_spell", DEFAULT_COMBAT_SPELL)
        selected_spell_index = 0
        magic_level = int(player_data.get("magic_level", 1) or 1)
        equipped_weapon = str((player_data.get("equipment", {}) or {}).get("weapon", "") or "")
        for spell_id, spec in COMBAT_MAGIC_SPELL_DATA.items():
            spell_combo.addItem(str(spec.get("display_name", spell_id)), spell_id)
            spell_index = spell_combo.count() - 1
            gate = str(spec.get("quest_gate", "") or "")
            gate_done = True
            if gate == "mage_arena":
                gate_done = bool((player_data.get("mage_arena", {}) or {}).get("completed"))
            elif gate:
                gate_done = bool(((player_data.get("quests", {}) or {}).get(gate) or {}).get("completed"))
            required_weapon = str(spec.get("required_weapon", "") or "")
            unlocked = (
                magic_level >= int(spec.get("required_magic_level", 1) or 1)
                and gate_done
                and (not required_weapon or equipped_weapon == required_weapon)
            )
            spell_combo.model().item(spell_index).setEnabled(unlocked)
            if spell_id == current_spell:
                selected_spell_index = spell_index
        spell_combo.setCurrentIndex(selected_spell_index)
        if on_set_combat_spell is not None:
            spell_combo.currentIndexChanged.connect(
                lambda _index: on_set_combat_spell(spell_combo.currentData() or DEFAULT_COMBAT_SPELL)
            )
        spell_layout.addWidget(spell_label)
        spell_layout.addWidget(spell_combo, 1)
        layout.addWidget(spell_row)
        spell_row.setVisible(_combat_mode_text().lower().startswith("magic"))

        borrowed_row = QWidget()
        borrowed_row.setObjectName("combatBorrowedPowerRow")
        borrowed_layout = QVBoxLayout(borrowed_row)
        borrowed_layout.setContentsMargins(0, 0, 0, 0)
        borrowed_layout.setSpacing(4)
        borrowed_name = QLabel()
        borrowed_name.setObjectName("combatBorrowedPowerSpell")
        borrowed_name.setStyleSheet("color: palette(text);")
        borrowed_layout.addWidget(borrowed_name)
        borrowed_button = QPushButton()
        borrowed_button.setObjectName("combatBorrowedPowerButton")
        borrowed_button.setCheckable(True)
        borrowed_button.setToolTip(
            "The next Combat review performs one manual Borrowed Power cast, "
            "then returns to the selected autocast."
        )
        borrowed_layout.addWidget(borrowed_button)
        layout.addWidget(borrowed_row)
        borrowed_spell_ref = {"id": ""}

        def _set_borrowed_power_armed(checked: bool) -> None:
            spell_id = borrowed_spell_ref["id"]
            if on_set_combat_prayer_config is not None:
                on_set_combat_prayer_config(
                    "combat_borrowed_power_spell",
                    spell_id if checked else "",
                )
            borrowed_button.setText(
                "One cast armed"
                if checked
                else "Cast once next review"
            )

        borrowed_button.clicked.connect(_set_borrowed_power_armed)

        def _refresh_borrowed_power_row() -> None:
            current = arcane_capacitor_status_pure(player_data)
            spell_id = str(current["spell_id"])
            borrowed_spell_ref["id"] = spell_id
            spell_name = str(
                COMBAT_MAGIC_SPELL_DATA.get(
                    spell_id,
                    {},
                ).get("display_name", spell_id)
            )
            charges = int(current["charges"])
            borrowed_name.setText(
                f"Borrowed Power · {spell_name} · {charges:,} charges"
            )
            borrowed_name.setToolTip(
                f"{charges:,} Arcane capacitor charges remaining."
            )
            visible = bool(
                current["equipped"]
                and spell_id in BORROWED_POWER_COMBAT_SPELLS
                and _combat_mode_text().lower().startswith("magic")
            )
            armed = bool(
                visible
                and player_data.get("combat_borrowed_power_spell") == spell_id
            )
            borrowed_button.blockSignals(True)
            borrowed_button.setChecked(armed)
            borrowed_button.setText(
                "One cast armed"
                if armed
                else "Cast once next review"
            )
            borrowed_button.setEnabled(
                visible and on_set_combat_prayer_config is not None
            )
            borrowed_button.blockSignals(False)
            borrowed_row.setVisible(visible)

        _refresh_borrowed_power_row()

        casual_toggles = QWidget()
        casual_toggles.setObjectName("combatMagicCasualControls")
        casual_layout = QHBoxLayout(casual_toggles)
        casual_layout.setContentsMargins(0, 0, 0, 0)
        prayer_master = QCheckBox("Prayers/Curses")
        prayer_master.setObjectName("combatPrayerMasterCheck")
        prayer_master.setChecked(bool(player_data.get("combat_prayers_enabled", True)))
        dream_thrift = QCheckBox("Dream thrift")
        dream_thrift.setObjectName("combatDreamThriftCheck")
        dream_thrift.setChecked(bool(player_data.get("combat_dream_thrift", False)))
        if on_set_combat_prayer_config is not None:
            prayer_master.toggled.connect(lambda enabled: on_set_combat_prayer_config("combat_prayers_enabled", bool(enabled)))
            dream_thrift.toggled.connect(lambda enabled: on_set_combat_prayer_config("combat_dream_thrift", bool(enabled)))
        casual_layout.addWidget(prayer_master)
        casual_layout.addWidget(dream_thrift)
        casual_layout.addStretch(1)
        layout.addWidget(casual_toggles)

        auto_eat_row = QWidget()
        auto_eat_layout = QHBoxLayout(auto_eat_row)
        auto_eat_layout.setContentsMargins(0, 0, 0, 0)
        auto_eat_layout.setSpacing(8)
        threshold_label = QLabel("Auto-eat")
        threshold_label.setStyleSheet("color: palette(text);")
        threshold_spin = QSpinBox()
        threshold_spin.setObjectName("combatAutoEatThresholdSpin")
        threshold_spin.setRange(1, 99)
        threshold_spin.setSuffix("%")
        try:
            threshold_value = int(player_data.get("combat_auto_eat_threshold_percent", 40) or 40)
        except (TypeError, ValueError):
            threshold_value = 40
        threshold_spin.setValue(max(1, min(threshold_value, 99)))
        if on_set_combat_auto_eat_threshold is not None:
            threshold_spin.valueChanged.connect(lambda value: on_set_combat_auto_eat_threshold(value))
        auto_eat_layout.addWidget(threshold_label)
        auto_eat_layout.addWidget(threshold_spin, 1)
        layout.addWidget(auto_eat_row)

        advanced_toggle = QToolButton()
        advanced_toggle.setObjectName("combatAdvancedPresetToggle")
        advanced_toggle.setText("Advanced preset editor")
        advanced_toggle.setCheckable(True)
        advanced_toggle.setChecked(False)
        layout.addWidget(advanced_toggle)
        advanced_panel = QWidget()
        advanced_panel.setObjectName("combatAdvancedPresetPanel")
        advanced_layout = QVBoxLayout(advanced_panel)
        advanced_layout.setContentsMargins(0, 0, 0, 0)
        advanced_layout.setSpacing(8)
        advanced_panel.setVisible(False)
        advanced_toggle.toggled.connect(advanced_panel.setVisible)
        layout.addWidget(advanced_panel)

        prayer_header = QLabel("Prayer")
        prayer_header.setStyleSheet("color: palette(text); font-weight: 600;")
        advanced_layout.addWidget(prayer_header)

        prayer_controls = QWidget()
        prayer_controls_layout = QHBoxLayout(prayer_controls)
        prayer_controls_layout.setContentsMargins(0, 0, 0, 0)
        prayer_controls_layout.setSpacing(8)
        preset_combo = QComboBox()
        preset_combo.setObjectName("combatPresetCombo")
        presets = player_data.get("combat_presets", {}) or {}
        active_preset = str(player_data.get("combat_active_preset", "Default"))
        for name in presets if isinstance(presets, dict) else ("Default",):
            preset_combo.addItem(str(name), str(name))
        preset_combo.setCurrentText(active_preset)
        if on_set_combat_prayer_config is not None:
            preset_combo.currentTextChanged.connect(lambda name: on_set_combat_prayer_config("apply_preset", name))
        prayer_controls_layout.addWidget(QLabel("Preset"))
        prayer_controls_layout.addWidget(preset_combo, 1)
        save_preset = QPushButton("Save current…")
        save_preset.setObjectName("combatSavePresetButton")
        if on_set_combat_prayer_config is not None:
            def _save_current_preset() -> None:
                name, accepted = QInputDialog.getText(save_preset, "Save combat preset", "Preset name")
                if accepted and name.strip():
                    on_set_combat_prayer_config("save_preset", name.strip())
            save_preset.clicked.connect(_save_current_preset)
        prayer_controls_layout.addWidget(save_preset)

        book_combo = QComboBox()
        book_combo.setObjectName("combatPrayerBookCombo")
        book_combo.addItem("Standard prayers", "standard")
        temple_done = bool(((player_data.get("quests", {}) or {}).get("the_temple_at_senntisten") or {}).get("completed"))
        book_combo.addItem("Ancient Curses", "curses")
        curses_index = book_combo.findData("curses")
        if curses_index >= 0:
            book_combo.model().item(curses_index).setEnabled(temple_done)
        book_combo.setCurrentIndex(max(0, book_combo.findData(player_data.get("combat_prayer_book", "standard"))))
        if on_set_combat_prayer_config is not None:
            book_combo.currentIndexChanged.connect(lambda _i: on_set_combat_prayer_config("combat_prayer_book", book_combo.currentData()))
        prayer_controls_layout.addWidget(book_combo)

        uptime_combo = QComboBox()
        uptime_combo.setObjectName("combatPrayerUptimeCombo")
        for label, value in (("Off", "off"), ("Conservative 40%", "40"), ("Aggressive 70%", "70"), ("Always 100%", "100")):
            uptime_combo.addItem(label, value)
        uptime_combo.setCurrentIndex(max(0, uptime_combo.findData(player_data.get("combat_prayer_uptime", "off"))))
        if on_set_combat_prayer_config is not None:
            uptime_combo.currentIndexChanged.connect(lambda _i: on_set_combat_prayer_config("combat_prayer_uptime", uptime_combo.currentData()))
        prayer_controls_layout.addWidget(uptime_combo)
        advanced_layout.addWidget(prayer_controls)

        magic_advanced = QWidget()
        magic_advanced_layout = QHBoxLayout(magic_advanced)
        magic_advanced_layout.setContentsMargins(0, 0, 0, 0)
        vengeance_check = QCheckBox("Vengeance")
        vengeance_check.setObjectName("combatVengeanceCheck")
        vengeance_check.setChecked(bool(player_data.get("combat_vengeance", False)))
        swap_combo = QComboBox()
        swap_combo.setObjectName("combatSpellbookSwapCombo")
        swap_combo.addItem("No Spellbook Swap", "")
        swap_combo.addItem("Swap autocast", str(player_data.get("current_combat_spell", DEFAULT_COMBAT_SPELL)))
        swap_combo.addItem("Swap Vengeance", "vengeance")
        swap_combo.addItem("Swap Dream", "dream")
        swap_combo.setCurrentIndex(max(0, swap_combo.findData(str(player_data.get("combat_spellbook_swap", "") or ""))))
        if on_set_combat_prayer_config is not None:
            vengeance_check.toggled.connect(lambda enabled: on_set_combat_prayer_config("combat_vengeance", bool(enabled)))
            swap_combo.currentIndexChanged.connect(lambda _i: on_set_combat_prayer_config("combat_spellbook_swap", str(swap_combo.currentData() or "")))
        magic_advanced_layout.addWidget(vengeance_check)
        magic_advanced_layout.addWidget(QLabel("One off-book effect"))
        magic_advanced_layout.addWidget(swap_combo, 1)
        advanced_layout.addWidget(magic_advanced)

        target_id = str(player_data.get("current_combat_target", ""))
        target_pins = player_data.get("combat_target_presets", {}) or {}
        target_overrides = (player_data.get("combat_target_overrides", {}) or {}).get(target_id, {}) or {}
        preset_scope = QWidget()
        preset_scope_layout = QHBoxLayout(preset_scope)
        preset_scope_layout.setContentsMargins(0, 0, 0, 0)
        pin_preset = QCheckBox("Pin preset to this target")
        pin_preset.setObjectName("combatPinPresetCheck")
        pin_preset.setChecked(target_pins.get(target_id) == active_preset)
        override_prayers = QCheckBox("Override prayers")
        override_prayers.setObjectName("combatOverridePrayersCheck")
        override_prayers.setChecked("combat_selected_prayers" in target_overrides)
        override_uptime = QCheckBox("Override uptime")
        override_uptime.setObjectName("combatOverridePrayerUptimeCheck")
        override_uptime.setChecked("combat_prayer_uptime" in target_overrides)
        if on_set_combat_prayer_config is not None:
            pin_preset.toggled.connect(lambda enabled: on_set_combat_prayer_config("pin_target_preset", enabled))
            override_prayers.toggled.connect(lambda enabled: on_set_combat_prayer_config("target_override", ("combat_selected_prayers", enabled)))
            override_uptime.toggled.connect(lambda enabled: on_set_combat_prayer_config("target_override", ("combat_prayer_uptime", enabled)))
        preset_scope_layout.addWidget(pin_preset)
        preset_scope_layout.addWidget(override_prayers)
        preset_scope_layout.addWidget(override_uptime)
        advanced_layout.addWidget(preset_scope)

        hide_lower = QCheckBox("Hide lower-tier prayers")
        hide_lower.setObjectName("combatPrayerHideLowerCheck")
        advanced_layout.addWidget(hide_lower)
        prayer_grid = QWidget()
        prayer_grid.setObjectName("combatPrayerCheckboxGrid")
        prayer_grid_layout = QGridLayout(prayer_grid)
        prayer_grid_layout.setContentsMargins(0, 0, 0, 0)
        selected_prayers = set(player_data.get("combat_selected_prayers", ()) or ())
        prayer_level = int(player_data.get("prayer_level", 1) or 1)
        defence_level = int(player_data.get("defense_level", 1) or 1)
        knight_waves_done = bool((player_data.get("knight_waves", {}) or {}).get("completed"))
        current_book = str(player_data.get("combat_prayer_book", "standard"))
        prayer_checks = []

        def _on_prayer_toggled(prayer_id: str, checked: bool) -> None:
            selected = [str(pid) for pid in (player_data.get("combat_selected_prayers", ()) or ()) if str(pid) != prayer_id]
            if checked:
                selected.insert(0, prayer_id)
            if on_set_combat_prayer_config is not None:
                on_set_combat_prayer_config("combat_selected_prayers", selected)
                active = set(player_data.get("combat_selected_prayers", ()) or ())
                for prayer_check in prayer_checks:
                    prayer_check.blockSignals(True)
                    prayer_check.setChecked(str(prayer_check.property("prayerId")) in active)
                    prayer_check.blockSignals(False)

        visible_prayers = [prayer for prayer in COMBAT_PRAYERS if prayer.book == current_book]
        for index, prayer in enumerate(visible_prayers):
            level_copy = f"Lv {prayer.level} Prayer"
            if prayer.defence_level > 1:
                level_copy += f"; {prayer.defence_level} Defence"
            check = QCheckBox(f"{prayer.display_name} ({level_copy})")
            check.setObjectName(f"combatPrayerCheck::{prayer.id}")
            check.setChecked(prayer.id in selected_prayers)
            gate_done = True
            if prayer.quest_gate == "the_temple_at_senntisten":
                gate_done = temple_done
            elif prayer.quest_gate == "knight_waves":
                gate_done = knight_waves_done
            check.setEnabled(
                prayer.level <= prayer_level
                and prayer.defence_level <= defence_level
                and gate_done
            )
            if prayer.quest_gate == "knight_waves":
                requirements = [f"{prayer.level} Prayer"]
                if prayer.defence_level > 1:
                    requirements.append(f"{prayer.defence_level} Defence")
                check.setToolTip(
                    f"Requires {', '.join(requirements)}, and Knight Waves completion."
                )
            check.setProperty("prayerLevel", prayer.level)
            check.setProperty("prayerId", prayer.id)
            check.toggled.connect(lambda checked, pid=prayer.id: _on_prayer_toggled(pid, checked))
            prayer_grid_layout.addWidget(check, index // 3, index % 3)
            prayer_checks.append(check)
        hide_lower.toggled.connect(
            lambda hidden: [check.setVisible(not hidden or int(check.property("prayerLevel") or 1) >= max(1, prayer_level - 15)) for check in prayer_checks]
        )
        advanced_layout.addWidget(prayer_grid)

        auto_prayer = QCheckBox("Auto-bury/scatter combat drops (costs simulated ticks)")
        auto_prayer.setObjectName("combatAutoPrayerTrainingCheck")
        auto_prayer.setChecked(bool(player_data.get("combat_auto_prayer_training", False)))
        if on_set_combat_prayer_config is not None:
            auto_prayer.toggled.connect(lambda checked: on_set_combat_prayer_config("combat_auto_prayer_training", bool(checked)))
        advanced_layout.addWidget(auto_prayer)

        # ---- Loot from this enemy ----
        # Deciding what to pick up belongs with the live combat controls, not the
        # Bank tab. The default view is coarse: a value threshold plus a single
        # "keep everything" toggle. Per-drop overrides are opt-in behind an
        # "Advanced" disclosure, rendered as icon cells with a binary Keep | Drop
        # pill (neither segment lit = follow the value threshold).
        loot_header = QLabel("Loot")
        loot_header.setStyleSheet("color: palette(text); font-weight: 600;")
        layout.addWidget(loot_header)

        loot_row = QWidget()
        loot_row_layout = QHBoxLayout(loot_row)
        loot_row_layout.setContentsMargins(0, 0, 0, 0)
        loot_row_layout.setSpacing(8)
        loot_label = QLabel("Leave loot under")
        loot_label.setStyleSheet("color: palette(text);")
        loot_spin = QSpinBox()
        loot_spin.setObjectName("combatLootThresholdSpin")
        loot_spin.setRange(0, 100000)
        loot_spin.setSingleStep(5)
        loot_spin.setSuffix(" gp value")
        try:
            _loot_threshold = int(player_data.get("loot_value_threshold", inventory_pure.DEFAULT_LOOT_VALUE_THRESHOLD))
        except (TypeError, ValueError):
            _loot_threshold = inventory_pure.DEFAULT_LOOT_VALUE_THRESHOLD
        loot_spin.setValue(max(0, _loot_threshold))
        if on_set_loot_threshold is not None:
            loot_spin.valueChanged.connect(lambda value: on_set_loot_threshold(int(value)))
        loot_row_layout.addWidget(loot_label)
        loot_row_layout.addWidget(loot_spin, 1)
        layout.addWidget(loot_row)

        if loot_override_rows:
            _LOOT_MODES = ("auto", "keep", "leave")
            loot_cell_state: dict = {}
            loot_pill_refreshers: dict = {}

            def _apply_loot_cell(item_name: str, mode: str) -> None:
                loot_cell_state[item_name] = mode
                refresh = loot_pill_refreshers.get(item_name)
                if refresh is not None:
                    refresh(mode)

            keep_all_check = QCheckBox("Keep every drop from this enemy")
            keep_all_check.setObjectName("combatLootKeepAllCheck")

            def _sync_keep_all() -> None:
                names = [str(r.get("item", "")) for r in loot_override_rows if str(r.get("item", ""))]
                all_keep = bool(names) and all(loot_cell_state.get(n) == "keep" for n in names)
                keep_all_check.blockSignals(True)
                keep_all_check.setChecked(all_keep)
                keep_all_check.blockSignals(False)

            def _on_keep_all(checked: bool) -> None:
                mode = "keep" if checked else "auto"
                for _r in loot_override_rows:
                    name = str(_r.get("item", ""))
                    if not name:
                        continue
                    _apply_loot_cell(name, mode)
                    if on_set_loot_override is not None:
                        on_set_loot_override(name, mode)

            keep_all_check.toggled.connect(_on_keep_all)
            layout.addWidget(keep_all_check)

            loot_adv_check = QCheckBox("Advanced: keep or drop specific drops")
            loot_adv_check.setObjectName("combatLootAdvancedCheck")
            layout.addWidget(loot_adv_check)

            loot_grid_container = QWidget()
            loot_grid_container.setObjectName("combatLootOverrideGrid")
            loot_grid_layout = QGridLayout(loot_grid_container)
            loot_grid_layout.setContentsMargins(0, 2, 0, 2)
            loot_grid_layout.setSpacing(6)
            _LOOT_GRID_COLS = 2

            # Each drop gets a joined two-segment pill — Keep | Drop. Neither
            # segment lit means "Auto": that drop follows the "Leave loot under N
            # gp" threshold. Clicking a lit segment again clears back to Auto, so
            # the binary switch still reaches all three backend modes the engine
            # understands (auto / keep / leave).
            def _seg_css(side: str, active: bool, accent: str) -> str:
                radius = (
                    "border-top-left-radius:6px;border-bottom-left-radius:6px;border-right:none;"
                    if side == "left"
                    else "border-top-right-radius:6px;border-bottom-right-radius:6px;"
                )
                if active:
                    face = f"background:{accent};color:palette(text);font-weight:600;"
                else:
                    face = f"background:transparent;color:{dim_text_css(loot_grid_container)};"
                return (
                    f"QPushButton{{border:1px solid palette(mid);{radius}"
                    f"padding:2px 12px;font-size:11px;{face}}}"
                )

            def _set_loot_mode(name: str, new_mode: str) -> None:
                _apply_loot_cell(name, new_mode)
                if on_set_loot_override is not None:
                    on_set_loot_override(name, new_mode)
                _sync_keep_all()

            _cell_idx = 0
            for _r in loot_override_rows:
                item_name = str(_r.get("item", ""))
                if not item_name:
                    continue
                mode = str(_r.get("mode", "auto"))
                if mode not in _LOOT_MODES:
                    mode = "auto"
                cell = QWidget()
                cell.setObjectName(f"combatLootCell{_cell_idx}")
                cell_layout = QHBoxLayout(cell)
                cell_layout.setContentsMargins(2, 2, 2, 2)
                cell_layout.setSpacing(8)
                icon_label = QLabel()
                _def = _item_def_for(item_name)
                _icon = _bank_icon_path(item_name, _def.asset_path if _def is not None else None)
                if _icon:
                    icon_label.setPixmap(QPixmap(_icon).scaled(22, 22, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation))
                icon_label.setFixedWidth(24)
                name_label = QLabel(item_name)
                name_label.setStyleSheet("color: palette(text); font-size: 11px;")
                keep_btn = QPushButton("Keep")
                keep_btn.setObjectName(f"lootOverrideKeep::{item_name}")
                keep_btn.setFixedHeight(24)
                drop_btn = QPushButton("Drop")
                drop_btn.setObjectName(f"lootOverrideDrop::{item_name}")
                drop_btn.setFixedHeight(24)
                keep_btn.setEnabled(on_set_loot_override is not None)
                drop_btn.setEnabled(on_set_loot_override is not None)

                def _refresh_pill(new_mode: str, kb=keep_btn, db=drop_btn) -> None:
                    kb.setStyleSheet(_seg_css("left", new_mode == "keep", "rgba(76,175,80,0.35)"))
                    db.setStyleSheet(_seg_css("right", new_mode == "leave", "rgba(192,69,59,0.35)"))

                loot_pill_refreshers[item_name] = _refresh_pill
                keep_btn.clicked.connect(
                    lambda _c=False, name=item_name: _set_loot_mode(
                        name, "auto" if loot_cell_state.get(name) == "keep" else "keep"
                    )
                )
                drop_btn.clicked.connect(
                    lambda _c=False, name=item_name: _set_loot_mode(
                        name, "auto" if loot_cell_state.get(name) == "leave" else "leave"
                    )
                )
                pill = QWidget()
                pill_layout = QHBoxLayout(pill)
                pill_layout.setContentsMargins(0, 0, 0, 0)
                pill_layout.setSpacing(0)
                pill_layout.addWidget(keep_btn)
                pill_layout.addWidget(drop_btn)
                cell_layout.addWidget(icon_label)
                cell_layout.addWidget(name_label, 1)
                cell_layout.addWidget(pill)
                _apply_loot_cell(item_name, mode)
                loot_grid_layout.addWidget(cell, _cell_idx // _LOOT_GRID_COLS, _cell_idx % _LOOT_GRID_COLS)
                _cell_idx += 1

            loot_grid_container.setVisible(False)
            loot_adv_check.toggled.connect(lambda checked: loot_grid_container.setVisible(bool(checked)))
            layout.addWidget(loot_grid_container)
            _sync_keep_all()

        def _refresh_combat_setup_panel() -> None:
            mode_label.setText(f"Combat mode: {_combat_mode_text()}")
            _rebuild_style_combo()
            _refresh_combat_action()
            _refresh_borrowed_power_row()

        _combat_setup_refreshers.append(_refresh_combat_setup_panel)

        layout.addStretch(1)
        return panel

    def _build_combat_skill_bars() -> QWidget:
        # Per-skill XP progress, the same read-out the gathering/artisan skills
        # get on the Stats screen — so the player can see combat XP land in
        # Attack/Strength/Defence/Constitution (and Ranged/Magic) individually
        # rather than as one opaque drop.
        box = QWidget()
        box_layout = QVBoxLayout(box)
        box_layout.setContentsMargins(0, 0, 0, 0)
        box_layout.setSpacing(4)
        heading = QLabel("Combat XP")
        heading.setStyleSheet("color: palette(text); font-weight: 600;")
        box_layout.addWidget(heading)
        grid = QGridLayout()
        grid.setContentsMargins(0, 0, 0, 0)
        grid.setHorizontalSpacing(8)
        grid.setVerticalSpacing(4)
        grid.setColumnStretch(2, 1)
        for row, (display, level_key, exp_key, default_level) in enumerate(_COMBAT_SKILL_BARS):
            level = int(player_data.get(level_key, default_level) or default_level)
            exp = round(player_data.get(exp_key, 0) or 0, 1)
            pct, remain, target_lv = compute_level_progress(level, exp, EXP_TABLE)
            name_lbl = QLabel(f"{display} Lv {level}")
            name_lbl.setStyleSheet("color: palette(text); font-size: 11px;")
            icon_lbl = QLabel()
            icon_lbl.setObjectName(
                f"combatXpIcon{display.replace(' ', '')}"
            )
            icon_lbl.setFixedSize(20, 20)
            icon_path = skill_icon_path_for(display)
            if icon_path:
                icon_lbl.setPixmap(
                    QPixmap(icon_path).scaled(
                        18,
                        18,
                        Qt.AspectRatioMode.KeepAspectRatio,
                        Qt.TransformationMode.FastTransformation,
                    )
                )
            bar = QProgressBar()
            bar.setTextVisible(False)
            bar.setFixedHeight(10)
            bar.setRange(0, 100)
            bar.setValue(pct)
            bar.setToolTip(
                f"{display}: level {level} • {exp:,.0f} XP"
                + (f" • {remain:,.0f} to Lv {target_lv}" if level < 99 else " • max level")
            )
            grid.addWidget(icon_lbl, row, 0)
            grid.addWidget(name_lbl, row, 1)
            grid.addWidget(bar, row, 2)
        box_layout.addLayout(grid)
        return box

    def _run_slayer_command(action_id: str, payload: dict) -> dict:
        if on_slayer_command is None:
            return {"ok": False, "message": "Slayer actions are unavailable."}
        result = on_slayer_command(action_id, payload) or {}
        if not result.get("ok", False):
            warn.setText(str(result.get("message", "That Slayer action is unavailable.")))
        else:
            warn.setText("")
        return result

    def _open_slayer_assignment_in_combat() -> None:
        result = _run_slayer_command("set_combat_filter", {"enabled": True})
        if not result.get("ok", False):
            return
        state["category"] = "combat"
        _update_cat_btn_styles()
        state["skill"] = _COMBAT_HUB_NAME
        _render_skill_list()
        _render_panel()
        tabs.setCurrentWidget(skills_tab)

