    def _build_combat_list() -> QWidget:
        container = QWidget()
        layout = QVBoxLayout(container)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(8)

        layout.addWidget(_build_combat_skill_bars())

        filter_bar = CatalogFilterBar(
            placeholder="Search combat targets",
            search_object_name="combatTargetSearchInput",
        )
        task_only = QCheckBox("Current Slayer task only")
        task_only.setObjectName("slayerTaskOnlyCheckBox")
        task_only.setChecked(bool(player_data.get("slayer_combat_filter", False)))
        task_only.setToolTip(
            "Show only enemies that count toward the active Slayer assignment."
        )
        filter_bar.add_filter(task_only)
        layout.addWidget(filter_bar)

        combat_images = _item_asset_paths()
        combat_rows = combat_target_rows(
            player_data,
            COMBAT_ENEMY_DATA,
            combat_images,
            EQUIPMENT_ITEM_DATA,
            DEFAULT_COMBAT_TARGET,
            COMBAT_ENEMY_IMAGES,
        )
        assignment_target_ids = set(
            slayer_target_ids_for_assignment_pure(player_data)
        )

        def _confirm_combat_target(row: TargetRowMetadata) -> bool:
            if not row.requires_confirmation:
                return True
            wilderness = bool(
                (COMBAT_ENEMY_DATA.get(row.target_id, {}) or {}).get(
                    "wilderness_risk"
                )
            )
            fingerprint = (
                wilderness_combat_risk_fingerprint(
                    player_data,
                    row.target_id,
                    COMBAT_ENEMY_DATA.get(row.target_id, {}) or {},
                )
                if wilderness
                else ""
            )
            if wilderness_combat_risk_confirmed(fingerprint):
                return True
            answer = QMessageBox.question(
                container,
                row.confirmation_title or "Confirm combat target",
                row.confirmation_message or "This combat target may kill you. Select it anyway?",
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No,
            )
            confirmed = answer == QMessageBox.StandardButton.Yes
            if confirmed and fingerprint:
                confirm_wilderness_combat_risk(fingerprint)
            return confirmed

        tree_host = QWidget()
        tree_layout = QVBoxLayout(tree_host)
        tree_layout.setContentsMargins(0, 0, 0, 0)
        tree_layout.setSpacing(0)
        live_tree = {"widget": None}

        def _render_combat_targets() -> None:
            previous = live_tree["widget"]
            if previous is not None:
                tree_layout.removeWidget(previous)
                previous.setParent(None)
                previous.deleteLater()

            filtered_rows = tuple(
                row
                for row in combat_rows
                if not task_only.isChecked()
                or row.target_id in assignment_target_ids
                if filter_bar.matches_text(
                    row.target_id,
                    row.label,
                    row.tooltip,
                    row.group,
                )
            )
            tree = _build_grouped_target_tree(
                filtered_rows,
                {group: group for group in COMBAT_TARGET_GROUP_ORDER},
                "__combat_group__:",
                on_set_combat,
                confirm_select=_confirm_combat_target,
                group_order=list(COMBAT_TARGET_GROUP_ORDER),
                expanded_groups=(
                    {row.group or "other" for row in filtered_rows}
                    if filter_bar.query() or task_only.isChecked()
                    else None
                ),
            )
            tree.setObjectName("combatTargetTree")
            if not filtered_rows:
                if task_only.isChecked() and not assignment_target_ids:
                    empty_text = (
                        "No active Slayer assignment. Untick the filter to see all "
                        "enemies, or get a new task from Slayer."
                    )
                elif task_only.isChecked() and filter_bar.query():
                    empty_text = "No assigned targets match this search."
                elif task_only.isChecked():
                    empty_text = "No playable enemies are available for this assignment."
                else:
                    empty_text = "No combat targets match this search."
                empty = QTreeWidgetItem([empty_text])
                empty.setFlags(Qt.ItemFlag.NoItemFlags)
                empty.setForeground(0, dim_text_color(tree))
                tree.addTopLevelItem(empty)
            filter_bar.set_count(len(filtered_rows), len(combat_rows))
            tree_layout.addWidget(tree)
            live_tree["widget"] = tree

        filter_bar.search_input.textChanged.connect(
            lambda _text="": _render_combat_targets()
        )

        def _set_task_only(enabled: bool) -> None:
            result = _run_slayer_command(
                "set_combat_filter", {"enabled": bool(enabled)}
            )
            if not result.get("ok", False):
                task_only.blockSignals(True)
                task_only.setChecked(not enabled)
                task_only.blockSignals(False)
            _render_combat_targets()

        task_only.toggled.connect(_set_task_only)
        _render_combat_targets()
        layout.addWidget(tree_host, 1)
        return container

    def _build_utility_list(surface_name: str) -> QWidget:
        is_activities = surface_name == _ACTIVITIES_HUB_NAME
        container = QWidget()
        container_layout = QVBoxLayout(container)
        container_layout.setContentsMargins(0, 0, 0, 0)
        container_layout.setSpacing(8)

        cards_stack = QStackedWidget()
        cards_stack.setObjectName("utilityActivityDetailsStack")
        cards_stack.setSizePolicy(
            QSizePolicy.Policy.Expanding,
            QSizePolicy.Policy.Fixed,
        )

        def _fit_current_activity_detail() -> None:
            current_card = cards_stack.currentWidget()
            if current_card is not None:
                cards_stack.setFixedHeight(
                    max(96, current_card.sizeHint().height())
                )

        star_panel_refresher = {"call": lambda: None}
        fog_panel_refresher = {"call": lambda: None}
        world_events_refresher = {"call": lambda: None}
        # Activity cards whose state changes while they are off screen register
        # a refresher here, and _show_activity_detail calls it on display.
        detail_card_refreshers: dict = {}
        # Tracked explicitly rather than read off cards_stack.isVisible(): under
        # offscreen Qt a never-shown dialog reports False right after
        # setVisible(True), which would silently break duplicate suppression.
        visible_detail_id = {"id": ""}

        familiarisation_box = QtFrame()
        familiarisation_box.setObjectName("familiarisationPanel")
