        livid_capacitor_layout.setContentsMargins(0, 2, 0, 0)
        livid_capacitor_layout.setSpacing(6)
        livid_capacitor_status = QLabel()
        livid_capacitor_status.setObjectName("lividFarmCapacitorStatus")
        livid_capacitor_status.setStyleSheet("color: palette(text);")
        livid_capacitor_spell = QComboBox()
        livid_capacitor_spell.setObjectName("lividFarmCapacitorSpell")
        livid_capacitor_spell.setMinimumContentsLength(12)
        livid_capacitor_spell.setSizeAdjustPolicy(
            QComboBox.SizeAdjustPolicy.AdjustToMinimumContentsLengthWithIcon
        )
        livid_capacitor_charge = QPushButton("Charge")
        livid_capacitor_charge.setObjectName("lividFarmCapacitorCharge")
        livid_capacitor_remove = QPushButton("Remove charge")
        livid_capacitor_remove.setObjectName("lividFarmCapacitorRemove")
        livid_capacitor_remove.setToolTip(
            "Destroy the necklace and refund the unused loaded spell runes."
        )
        livid_capacitor_layout.addWidget(livid_capacitor_status)
        livid_capacitor_layout.addWidget(livid_capacitor_spell, 1)
        livid_capacitor_layout.addWidget(livid_capacitor_charge)
        livid_capacitor_layout.addWidget(livid_capacitor_remove)
        livid_layout.addWidget(livid_capacitor_row)
        cards_stack.addWidget(livid_box)

        syncing_livid = {"active": False}

        def _refresh_livid_panel() -> None:
            syncing_livid["active"] = True
            livid_state = sanitize_livid_farm_state_pure(
                player_data.get("livid_farm")
            )
            projection = livid_farm_cycle_projection_pure(
                player_data,
                livid_state["farm_routine"],
            )
            locked = livid_farm_locked_reasons_pure(player_data)
            current_index = livid_routine.findData(
                livid_state["farm_routine"]
            )
            livid_routine.setCurrentIndex(max(0, current_index))
            livid_routine.setEnabled(
                on_livid_farm_command is not None and not locked
            )
            rune_text = ", ".join(
                f"{name.replace(' rune', '')} {amount}"
                for name, amount in projection["rune_cost"].items()
            )
            if locked:
                livid_status.setText("Locked · " + " · ".join(locked))
                livid_status.setToolTip("")
            else:
                status_text = (
                    f"{int(projection['points']):,} Produce/cycle · "
                    f"{int(livid_state['produce_points']):,} banked · "
                    f"{int(livid_state['cycles_completed']):,} cycles"
                )
                remaining = int(
                    livid_state["more_planks_reviews_remaining"]
                )
                if remaining > 0:
                    status_text += f" · More Planks {remaining} left"
                livid_status.setText(status_text)
                livid_status.setToolTip(
                    f"Runes per cycle after staff substitutions: "
                    f"{rune_text or 'none'}"
                )
            unlocked = set(livid_state["unlocked_spells"])
            next_unlock = None
            previous_threshold = 0
            for unlock_id, unlock_name, threshold in LIVID_FARM_UNLOCKS:
                if unlock_id not in unlocked:
                    next_unlock = (unlock_id, unlock_name, threshold)
                    break
                previous_threshold = threshold
            if next_unlock is None:
                livid_progress.setRange(0, 1)
                livid_progress.setValue(1)
                livid_progress.setFormat("All Livid Farm spells unlocked")
                livid_progress.setVisible(False)
            else:
                _unlock_id, unlock_name, threshold = next_unlock
                lifetime = int(livid_state["lifetime_produce_points"])
                segment_size = max(1, threshold - previous_threshold)
                segment_progress = max(
                    0,
                    min(lifetime - previous_threshold, segment_size),
                )
                livid_progress.setRange(0, segment_size)
                livid_progress.setValue(segment_progress)
                livid_progress.setFormat(
                    f"Next: {unlock_name} · {lifetime:,}/{threshold:,}"
                )
                livid_progress.setVisible(True)
            selected_wish = str(livid_wish_picker.currentData() or "")
            wish_rows = livid_farm_wish_rows_pure(player_data)
            livid_wish_picker.blockSignals(True)
            livid_wish_picker.clear()
            for wish in wish_rows:
                livid_wish_picker.addItem(
                    str(wish["display_name"]),
                    wish["id"],
                )
                index = livid_wish_picker.count() - 1
                livid_wish_picker.setItemData(
                    index,
                    wish["summary"],
                    Qt.ItemDataRole.ToolTipRole,
                )
                if not wish["enabled"]:
                    livid_wish_picker.setItemData(
                        index,
                        dim_text_color(livid_wish_picker),
                        Qt.ItemDataRole.ForegroundRole,
                    )
            selected_index = livid_wish_picker.findData(selected_wish)
            if selected_index < 0:
                selected_index = next(
                    (
                        index
                        for index, wish in enumerate(wish_rows)
                        if wish["enabled"]
                    ),
                    0,
                )
            livid_wish_picker.setCurrentIndex(selected_index)
            livid_wish_picker.blockSignals(False)
            selected_row = (
                wish_rows[selected_index]
                if 0 <= selected_index < len(wish_rows)
                else None
            )
            wish_surface_visible = bool(
                livid_state["borrowed_power_claimed"]
            )
            capacitor = arcane_capacitor_status_pure(player_data)
            selected_capacitor_spell = str(
                livid_capacitor_spell.currentData() or ""
            )
            capacitor_rows = arcane_capacitor_spell_rows_pure(player_data)
            livid_capacitor_spell.blockSignals(True)
            livid_capacitor_spell.clear()
            for row in capacitor_rows:
                livid_capacitor_spell.addItem(
                    str(row["display_name"]),
                    row["id"],
                )
                index = livid_capacitor_spell.count() - 1
                cost_text = ", ".join(
                    f"{name} x{amount:,}"
                    for name, amount in row["rune_cost"].items()
                )
                livid_capacitor_spell.setItemData(
                    index,
                    cost_text,
                    Qt.ItemDataRole.ToolTipRole,
                )
                if not row["enabled"]:
                    livid_capacitor_spell.setItemData(
                        index,
                        dim_text_color(livid_capacitor_spell),
                        Qt.ItemDataRole.ForegroundRole,
                    )
            capacitor_index = livid_capacitor_spell.findData(
                str(capacitor["spell_id"])
                if capacitor["charged_owned"]
                else selected_capacitor_spell
            )
            if capacitor_index < 0:
                capacitor_index = next(
                    (
                        index
                        for index, row in enumerate(capacitor_rows)
                        if row["enabled"]
                    ),
                    0,
                )
            livid_capacitor_spell.setCurrentIndex(capacitor_index)
            livid_capacitor_spell.blockSignals(False)
            selected_capacitor_row = (
                capacitor_rows[capacitor_index]
                if 0 <= capacitor_index < len(capacitor_rows)
                else None
            )
            bound_name = next(
                (
                    str(row["display_name"])
                    for row in capacitor_rows
                    if row["id"] == capacitor["spell_id"]
                ),
                str(capacitor["spell_id"]),
            )
            if capacitor["charged_owned"]:
                livid_capacitor_status.setText(
                    f"Capacitor · {int(capacitor['charges']):,}"
                )
                livid_capacitor_status.setToolTip(
                    f"{bound_name} loaded · "
                    f"{int(capacitor['charges']):,} charges remaining."
                )
            elif capacitor["uncharged_owned"]:
                livid_capacitor_status.setText("Capacitor · Uncharged")
                livid_capacitor_status.setToolTip(
                    "Uncharged capacitor ready to load."
                )
            elif capacitor["owned"]:
                livid_capacitor_status.setText("Capacitor · Stored")
                livid_capacitor_status.setToolTip(
                    "The capacitor is stored outside the Bank or equipment."
                )
            else:
                livid_capacitor_status.setText("Capacitor · None")
                livid_capacitor_status.setToolTip(
                    "Purchase an Arcane capacitor wish first."
                )
            magic_ready = (
                int(player_data.get("magic_level", 1) or 1) >= 99
            )
            can_charge = bool(
                livid_state["borrowed_power_claimed"]
                and capacitor["uncharged_owned"]
                and magic_ready
                and selected_capacitor_row
                and selected_capacitor_row["enabled"]
                and on_livid_farm_command is not None
            )
            charge_tooltip = ""
            if not livid_state["borrowed_power_claimed"]:
                charge_tooltip = "Unlock Borrowed Power first."
            elif not capacitor["uncharged_owned"]:
                charge_tooltip = "Carry an uncharged Arcane capacitor."
            elif not magic_ready:
                charge_tooltip = "Requires Magic level 99."
            elif (
                selected_capacitor_row
                and selected_capacitor_row["missing_runes"]
            ):
                charge_tooltip = "Missing " + ", ".join(
                    f"{name} x{amount:,}"
                    for name, amount in
                    selected_capacitor_row["missing_runes"].items()
                )
            livid_capacitor_charge.setToolTip(charge_tooltip)
            livid_capacitor_spell.setEnabled(
                bool(livid_state["borrowed_power_claimed"])
                and bool(capacitor["uncharged_owned"])
                and on_livid_farm_command is not None
            )
            livid_capacitor_charge.setEnabled(can_charge)
            livid_capacitor_remove.setEnabled(
                bool(capacitor["charged_owned"])
                and on_livid_farm_command is not None
            )
            livid_capacitor_row.setVisible(
                wish_surface_visible or bool(capacitor["owned"])
            )
            livid_box.setMinimumHeight(
                132
                if livid_capacitor_row.isVisible()
                else 96
                if wish_surface_visible
                else 78
            )
            livid_wish_row.setVisible(wish_surface_visible)
            if wish_surface_visible and selected_row is not None:
                livid_wish_button.setText(
                    f"Make wish · {int(selected_row['cost']):,}"
                )
                livid_wish_button.setEnabled(
                    bool(selected_row["enabled"])
                    and on_livid_farm_command is not None
                )
                wish_message = (
                    selected_row["locked_reason"]
                    or selected_row["summary"]
                )
                if selected_row["locked_reason"]:
                    livid_status.setText(
                        "Blocked · " + str(wish_message)
                    )
                livid_wish_picker.setToolTip(str(wish_message))
            livid_box.setVisible(
                not locked
                or int(livid_state["cycles_completed"]) > 0
                or player_data.get("current_utility") == "livid_farm"
            )
            syncing_livid["active"] = False
            _fit_current_activity_detail()

        def _set_livid_routine() -> None:
            if syncing_livid["active"] or on_livid_farm_command is None:
                return
            result = on_livid_farm_command(
                "set_routine",
                {"routine": livid_routine.currentData()},
            ) or {}
            if not result.get("ok", False) and result.get("message"):
                QMessageBox.warning(
                    container,
                    "Livid Farm",
                    str(result["message"]),
                )
            _refresh_livid_panel()

        def _buy_livid_wish() -> None:
            if syncing_livid["active"] or on_livid_farm_command is None:
                return
            result = on_livid_farm_command(
                "buy_wish",
                {"wish_id": str(livid_wish_picker.currentData() or "")},
            ) or {}
            if not result.get("ok", False) and result.get("message"):
                QMessageBox.warning(
                    container,
                    "Livid Farm",
                    str(result["message"]),
                )
            _refresh_livid_panel()

        def _charge_livid_capacitor() -> None:
            if syncing_livid["active"] or on_livid_farm_command is None:
                return
            result = on_livid_farm_command(
                "charge_capacitor",
                {
                    "spell_id": str(
                        livid_capacitor_spell.currentData() or ""
                    )
                },
            ) or {}
            if not result.get("ok", False) and result.get("message"):
                QMessageBox.warning(
                    container,
                    "Arcane capacitor",
                    str(result["message"]),
                )
            _refresh_livid_panel()

        def _remove_livid_capacitor_charge() -> None:
            if syncing_livid["active"] or on_livid_farm_command is None:
                return
            answer = QMessageBox.question(
                container,
                "Remove Arcane capacitor charge?",
                (
                    "This refunds the unused loaded runes but destroys the "
                    "Arcane capacitor necklace. Continue?"
                ),
                QMessageBox.StandardButton.Yes
                | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No,
            )
            if answer != QMessageBox.StandardButton.Yes:
                return
            result = on_livid_farm_command(
                "remove_capacitor_charge",
                {},
            ) or {}
            if not result.get("ok", False) and result.get("message"):
                QMessageBox.warning(
                    container,
                    "Arcane capacitor",
                    str(result["message"]),
                )
            _refresh_livid_panel()

        livid_routine.currentIndexChanged.connect(
            lambda _index: _set_livid_routine()
        )
        livid_wish_picker.currentIndexChanged.connect(
            lambda _index: _refresh_livid_panel()
        )
        livid_wish_button.clicked.connect(
            lambda _checked=False: _buy_livid_wish()
        )
        livid_capacitor_spell.currentIndexChanged.connect(
            lambda _index: _refresh_livid_panel()
        )
        livid_capacitor_charge.clicked.connect(
            lambda _checked=False: _charge_livid_capacitor()
        )
        livid_capacitor_remove.clicked.connect(
            lambda _checked=False: _remove_livid_capacitor_charge()
        )
        _refresh_livid_panel()

        tree = QTreeWidget()
        tree.setObjectName("utilityActivityTree")
        tree.setHeaderHidden(True)
        tree.setIconSize(QSize(28, 28))
        tree.setRootIsDecorated(True)
        tree.setIndentation(14)
        tree.setUniformRowHeights(True)
        tree_base = tree.palette().color(QPalette.ColorRole.Base)
        activity_selection = QColor(
            round((tree_base.red() * 0.70) + (76 * 0.30)),
            round((tree_base.green() * 0.70) + (175 * 0.30)),
            round((tree_base.blue() * 0.70) + (80 * 0.30)),
        ).name()
        tree.setStyleSheet(
            "QTreeWidget { border: 1px solid palette(mid); border-radius: 8px;"
            " background: palette(base); color: palette(text); padding: 4px; }"
            " QTreeWidget::item { min-height: 32px; padding: 5px;"
            " border-radius: 6px; }"
            f" QTreeWidget::item:selected {{ background: {activity_selection};"
            " color: palette(text); }"
            f" QTreeWidget::branch:selected {{ background: {activity_selection}; }}"
            f" QTreeWidget::item:disabled {{ color: {dim_text_css(tree)}; }}"
        )
        rows = utility_activity_rows(
            player_data,
            UTILITY_ACTIVITY_DATA,
            {**UTILITY_ITEM_IMAGES, **COOKING_ITEM_IMAGES},
            BIRD_NEST_OPEN_TABLES,
            DEFAULT_UTILITY_ACTIVITY,
            QUEST_UNLOCK_RULES,
        )
        surface_id = ACTIVITY_SURFACE_ID if is_activities else UTILITY_SURFACE_ID
        rows = tuple(
            row
            for row in rows
            if UTILITY_ACTIVITY_DATA.get(row.target_id, {}).get("surface")
            == surface_id
        )
        current = player_data.get("current_utility", DEFAULT_UTILITY_ACTIVITY)
        ordered_groups = list(_UTILITY_GROUP_LABELS)
        groups = {group: [] for group in ordered_groups}
        for row in rows:
            spec = UTILITY_ACTIVITY_DATA.get(row.target_id, {})
            group = str(spec.get("group", "material_processing"))
            if group not in groups:
                groups[group] = []
                ordered_groups.append(group)
            groups[group].append(row)

        collapsed_activity_groups = (
            activity_collapsed_groups() if is_activities else set()
        )
        selected_child = None
        for group in ordered_groups:
            group_rows = groups.get(group, [])
            if not group_rows or (is_activities and group == "landmarks"):
                continue
            label = _UTILITY_GROUP_LABELS.get(group, group.replace("_", " ").title())
            parent_text = f"{label}  ({len(group_rows)})"
            parent = QTreeWidgetItem([parent_text])
            parent.setData(0, Qt.ItemDataRole.UserRole, f"__utility_group__:{group}")
            parent.setFlags(Qt.ItemFlag.ItemIsEnabled)
            group_icon = _ACTIVITY_GROUP_ICONS.get(group)
            if group_icon and os.path.exists(group_icon):
                icon = _pixel_path_icon(group_icon, 28)
                if icon is not None:
                    parent.setIcon(0, icon)
            font = parent.font(0)
            font.setBold(True)
            parent.setFont(0, font)
            tree.addTopLevelItem(parent)
            group_has_current = False
            for row in group_rows:
                child = QTreeWidgetItem([row.label])
                child.setData(0, Qt.ItemDataRole.UserRole, row.target_id)
                if row.icon_path and os.path.exists(row.icon_path):
                    icon = _pixel_path_icon(row.icon_path, 28)
                    if icon is not None:
                        child.setIcon(0, icon)
                if (
                    not row.enabled
                    and row.target_id
                    not in {
                        WEREWOLF_SKULLBALL_ACTIVITY_ID,
                        GNOME_BALL_ACTIVITY_ID,
                        FISHING_TRAWLER_ACTIVITY_ID,
                        GREAT_ORB_PROJECT_ACTIVITY_ID,
                        MANAGING_MISCELLANIA_ACTIVITY_ID,
                    }
                ):
                    child.setDisabled(True)
                child.setToolTip(0, row.tooltip)
                parent.addChild(child)
                if row.target_id == current:
                    selected_child = child
                    group_has_current = True
            if is_activities:
                parent.setExpanded(group not in collapsed_activity_groups)
            else:
                parent.setExpanded(group_has_current)

        # Landmarks: the one-time Stronghold of Security. Injected by hand because
        # it is a step counter, not a repeatable UTILITY_ACTIVITY_DATA activity.
        sh_state = player_data.get("stronghold_of_security") or {}
        sh_completed = bool(sh_state.get("completed"))
        sh_claimed = sh_state.get("boots_choice") is not None
        sh_step = max(0, min(int(sh_state.get("step", 0) or 0), STRONGHOLD_TOTAL_STEPS))
        if sh_completed and not sh_claimed:
            sh_label = "Stronghold of Security — Claim your reward ✨"
            sh_tooltip = (
                f"Cleared! Click to choose your boots and collect {STRONGHOLD_REWARD_COINS:,} coins."
            )
        elif sh_completed:
            sh_label = f"Stronghold of Security ✓  ({sh_state.get('boots_choice')})"
            sh_tooltip = "Completed. Reward already claimed."
        else:
            next_name = STRONGHOLD_STEP_NAMES[sh_step] if sh_step < STRONGHOLD_TOTAL_STEPS else STRONGHOLD_STEP_NAMES[-1]
            sh_label = f"Stronghold of Security — {sh_step}/{STRONGHOLD_TOTAL_STEPS}  (next: {next_name})"
            sh_tooltip = (
                "A one-time landmark. Set it as your activity and each review clears "
                "one level. No XP along the way, but coins and boots at the end."
            )
        landmark_rows = groups.get("landmarks", []) if is_activities else []
        landmark_count = 3 + len(landmark_rows)
        landmark_parent = QTreeWidgetItem([f"Landmarks  ({landmark_count})"])
        landmark_parent.setData(0, Qt.ItemDataRole.UserRole, "__utility_group__:landmarks")
        landmark_parent.setFlags(Qt.ItemFlag.ItemIsEnabled)
        lm_font = landmark_parent.font(0)
        lm_font.setBold(True)
        landmark_parent.setFont(0, lm_font)
        if is_activities:
            tree.addTopLevelItem(landmark_parent)
        sh_child = QTreeWidgetItem([sh_label])
        sh_child.setData(0, Qt.ItemDataRole.UserRole, _STRONGHOLD_UTILITY_KEY)
        sh_child.setToolTip(0, sh_tooltip)
        sh_icon = os.path.join(current_dir, "icon", "attack_icon.png")
        if os.path.exists(sh_icon):
            icon = _pixel_path_icon(sh_icon, 28)
            if icon is not None:
                sh_child.setIcon(0, icon)
        if sh_completed and sh_claimed:
            sh_child.setDisabled(True)
        landmark_parent.addChild(sh_child)
        for row in landmark_rows:
            child = QTreeWidgetItem([row.label])
            child.setData(0, Qt.ItemDataRole.UserRole, row.target_id)
            if row.icon_path and os.path.exists(row.icon_path):
                icon = _pixel_path_icon(row.icon_path, 28)
                if icon is not None:
                    child.setIcon(0, icon)
            child.setToolTip(0, row.tooltip)
            landmark_parent.addChild(child)
            if row.target_id == current:
                selected_child = child
                landmark_parent.setExpanded(True)

        kw_state = player_data.get("knight_waves") or {}
        kw_step = max(0, min(int(kw_state.get("step", 0) or 0), KNIGHT_WAVES_TOTAL_STEPS))
        kw_completed = bool(kw_state.get("completed"))
        kw_locked = knight_waves_locked_reasons_pure(player_data)
        kw_label = "Knight Waves Training Ground ✓" if kw_completed else f"Knight Waves Training Ground — {kw_step}/{KNIGHT_WAVES_TOTAL_STEPS}"
        kw_child = QTreeWidgetItem([kw_label])
        kw_child.setData(0, Qt.ItemDataRole.UserRole, _KNIGHT_WAVES_UTILITY_KEY)
        kw_child.setToolTip(
            0,
            "Defeat eight knights, one per review. Completion grants 20,000 XP in Attack, Strength, Defence, and Constitution and unlocks Chivalry/Piety."
            + (f"\nLocked due to: {', '.join(kw_locked)}" if kw_locked and not kw_completed else ""),
        )
        kw_icon = os.path.join(current_dir, "icon", "prayer_icon.png")
        if os.path.exists(kw_icon):
            icon = _pixel_path_icon(kw_icon, 28)
            if icon is not None:
                kw_child.setIcon(0, icon)
        if kw_completed or kw_locked:
            kw_child.setDisabled(True)
        landmark_parent.addChild(kw_child)
        ma_state = sanitize_mage_arena_state_pure(player_data.get("mage_arena"))
        ma_step = max(0, min(int(ma_state.get("step", 0) or 0), MAGE_ARENA_TOTAL_STEPS))
        ma_completed = bool(ma_state.get("completed"))
        ma_alignment = str(ma_state.get("alignment", "") or "")
        ma_locked = mage_arena_locked_reasons_pure(player_data)
        alignment_label = (
            MAGE_ARENA_GOD_DATA[ma_alignment]["display_name"]
            if ma_alignment in MAGE_ARENA_GOD_DATA
            else ""
        )
        ma_label = (
            f"Mage Arena ✓ · {alignment_label or 'choose alignment'}"
            if ma_completed
            else f"Mage Arena — {ma_step}/{MAGE_ARENA_TOTAL_STEPS} Kolodion forms"
        )
        ma_child = QTreeWidgetItem([ma_label])
        ma_child.setData(0, Qt.ItemDataRole.UserRole, _MAGE_ARENA_UTILITY_KEY)
        ma_child.setToolTip(0, "Defeat Kolodion's five forms, one per review. Choose an alignment before the final form; completion grants its cape, staff, and attunement."
                            + (f"\nLocked due to: {', '.join(ma_locked)}" if ma_locked and not ma_completed else ""))
        ma_icon = os.path.join(current_dir, "icon", "magic_icon.png")
        if os.path.exists(ma_icon):
            icon = _pixel_path_icon(ma_icon, 28)
            if icon is not None:
                ma_child.setIcon(0, icon)
        if ma_completed or ma_locked:
            ma_child.setDisabled(True)
        landmark_parent.addChild(ma_child)
        if ma_step == MAGE_ARENA_TOTAL_STEPS - 1 and not ma_completed:
            alignment_parent = QTreeWidgetItem(["Choose alignment for the final form"])
            alignment_parent.setFlags(Qt.ItemFlag.ItemIsEnabled)
            landmark_parent.addChild(alignment_parent)
            for god_id, row in MAGE_ARENA_GOD_DATA.items():
                alignment_item = QTreeWidgetItem([row["display_name"]])
                alignment_item.setData(
                    0,
                    Qt.ItemDataRole.UserRole,
                    f"__mage_alignment__:{god_id}",
                )
                alignment_item.setToolTip(
                    0,
                    f"Final victory grants the {row['cape']} and {row['staff']} and attunes {row['spell_name']}.",
                )
                alignment_parent.addChild(alignment_item)
            alignment_parent.setExpanded(True)
        if ma_completed:
            statue_parent = QTreeWidgetItem(["Mage Arena statues"])
            statue_parent.setFlags(Qt.ItemFlag.ItemIsEnabled)
            landmark_parent.addChild(statue_parent)
            inventory = player_data.get("inventory", {}) or {}
            equipment = player_data.get("equipment", {}) or {}
            attuned = set(ma_state.get("attuned_spells", ()))
            for god_id, row in MAGE_ARENA_GOD_DATA.items():
                cape_label = (
                    f"Choose {row['cape']}"
                    if not ma_alignment
                    else (
                        f"Reclaim {row['cape']}"
                        if god_id == ma_alignment
                        else f"Switch to {row['cape']}"
                    )
                )
                cape_item = QTreeWidgetItem([cape_label])
                cape_item.setData(
                    0,
                    Qt.ItemDataRole.UserRole,
                    f"__mage_cape__:{god_id}",
                )
                cape_item.setToolTip(
                    0,
                    "Instant statue action. Any other god cape is destroyed or replaced; only one may be owned.",
                )
                statue_parent.addChild(cape_item)
                if row["spell_id"] not in attuned:
                    staff_owned = (
                        int(inventory.get(row["staff"], 0) or 0) > 0
                        or row["staff"] in equipment.values()
                    )
                    attune_item = QTreeWidgetItem(
                        [f"Attune {row['spell_name']} · one review"]
                    )
                    attune_item.setData(
                        0,
                        Qt.ItemDataRole.UserRole,
                        f"mage_arena_attune:{god_id}",
                    )
                    attune_item.setToolTip(
                        0,
                        f"Represents 100 arena casts. Requires owning {row['staff']}."
                        + ("" if staff_owned else f"\nMissing {row['staff']}."),
                    )
                    attune_item.setDisabled(not staff_owned)
                    statue_parent.addChild(attune_item)
            statue_parent.setExpanded(
                str(current).startswith("mage_arena_attune:")
            )
        landmark_active = False
        if current == _KNIGHT_WAVES_UTILITY_KEY and not kw_completed:
            selected_child = kw_child
            landmark_active = True
        if current == _MAGE_ARENA_UTILITY_KEY and not ma_completed:
            selected_child = ma_child
            landmark_active = True
        if current == _STRONGHOLD_UTILITY_KEY and not sh_completed:
            selected_child = sh_child
            landmark_active = True
        if is_activities:
            landmark_parent.setExpanded("landmarks" not in collapsed_activity_groups)
        else:
            landmark_parent.setExpanded(
                landmark_active or (sh_completed and not sh_claimed)
            )

        if selected_child is not None:
            ancestor = selected_child.parent()
            while ancestor is not None:
                ancestor.setExpanded(True)
                ancestor = ancestor.parent()
            tree.setCurrentItem(selected_child)
            tree.scrollToItem(
                selected_child,
                QAbstractItemView.ScrollHint.PositionAtCenter,
            )

        def _activity_group_id(item) -> Optional[str]:
            role = item.data(0, Qt.ItemDataRole.UserRole)
            prefix = "__utility_group__:"
            if isinstance(role, str) and role.startswith(prefix):
                return role[len(prefix):]
            return None

        if is_activities:
            tree.itemExpanded.connect(
                lambda item: (
                    _activity_group_id(item)
                    and set_activity_group_collapsed(_activity_group_id(item), False)
                )
            )
            tree.itemCollapsed.connect(
                lambda item: (
                    _activity_group_id(item)
                    and set_activity_group_collapsed(_activity_group_id(item), True)
                )
            )

