    ge_log_list.setMaximumHeight(110)
    ge_log_list.setSelectionMode(QAbstractItemView.SelectionMode.NoSelection)
    ge_log_list.setFocusPolicy(Qt.FocusPolicy.NoFocus)
    ge_log_list.setAlternatingRowColors(False)
    ge_layout.addWidget(ge_log_list)

    ge_state = {
        "projection": {
            "ironman_mode": False,
            "lock_reason": None,
            "coins": int((player_data.get("inventory") or {}).get("Coins", 0) or 0),
            "settings": {
                "high_value_confirmation": 1_000_000,
                "low_price_multiplier": 0.1,
                "high_price_multiplier": 10.0,
            },
            "slots": (None,) * GE_SLOT_COUNT,
            "items": (),
        },
        "selected_order_id": None,
        "selected_item_name": "",
        "editing_order_id": None,
    }

    def _ge_reason_message(result) -> str:
        reason = str((result or {}).get("reason", ""))
        messages = {
            "unknown_item": "That item is not available on the Grand Exchange.",
            "untradeable_item": "That item cannot be traded.",
            "not_exchangeable": "That item is not Grand Exchange eligible.",
            "invalid_offer": "Enter a positive quantity and price.",
            "no_offer_slot": f"All {GE_SLOT_COUNT} offer slots are occupied.",
            "guide_price_unavailable": "This item has no usable guide price.",
            "buy_limit_unavailable": "This item has no unambiguous period buy limit.",
            "insufficient_coins": "You do not have enough Coins for that offer.",
            "insufficient_items": "Your Bank does not contain that quantity.",
            "offers_must_be_cleared": "Clear all Grand Exchange slots before enabling Ironman mode.",
            "nothing_to_collect": "That offer has nothing ready to collect.",
            "order_not_open": "That offer can no longer be cancelled.",
            "unknown_order": "That offer no longer exists.",
            "ironman_mode": "Grand Exchange access is disabled in Ironman mode.",
            "confirmation_required": "Confirm the unusual offer before continuing.",
            "invalid_settings": "Enter valid Grand Exchange safety thresholds.",
            "undo_unavailable": "Anki could not create an undo entry.",
        }
        return str((result or {}).get("message") or messages.get(reason) or reason.replace("_", " ").capitalize())

    def _ge_current_item():
        selected_name = str(ge_state.get("selected_item_name", ""))
        for row in ge_state["projection"].get("items", ()):
            if row.get("item_name") == selected_name:
                return row
        return None

    def _refresh_ge_preview() -> None:
        row = _ge_current_item()
        locked = bool(ge_state["projection"].get("ironman_mode"))
        editing_order = _selected_ge_order()
        editing = (
            editing_order is not None
            and editing_order.get("id") == ge_state.get("editing_order_id")
            and editing_order.get("status") in {"open", "partial"}
        )
        enabled = (
            row is not None
            and callable(on_ge_action)
            and not locked
            and (not editing or editing_order is not None)
        )
        ge_submit.setEnabled(enabled)
        for button in ge_price_buttons.values():
            button.setEnabled(enabled)
        side = str(ge_side.currentData() or "buy")
        # Sell-only: the buy side would need a live buy-limit-remaining figure,
        # which the projection does not expose.
        ge_sell_all.setVisible(side == "sell")
        ge_sell_all.setEnabled(enabled)
        ge_side.setEnabled(not editing)
        ge_quantity_caption.setText("Remaining quantity" if editing else "Quantity")
        ge_submit.setText(
            "Update offer"
            if editing
            else ("Place buy offer" if side == "buy" else "Place sell offer")
        )
        if row is None:
            ge_selected_item.setText("Select an item")
            ge_item_meta.setText("Guide price and buy limit appear here.")
            ge_preview.setText("Choose an item to prepare an offer.")
            return
        guide = max(int(row.get("guide_price", 1) or 1), 1)
        owned = max(int(row.get("owned", 0) or 0), 0)
        buy_limit = row.get("buy_limit")
        limit_text = f"{int(buy_limit):,}" if buy_limit else "unavailable"
        ge_selected_item.setText(str(row["item_name"]))
        ge_item_meta.setText(
            f"Guide: {guide:,} Coins · Buy limit per 40 cards: {limit_text} · "
            f"Bank: {owned:,}"
        )
        total = int(ge_quantity.value()) * int(ge_price.value())
        ge_preview.setText(
            f"{'Update' if editing else side.title()} "
            f"{int(ge_quantity.value()):,} × {int(ge_price.value()):,} Coins"
            f" · Total {total:,} Coins"
        )

    def _populate_ge_items() -> None:
        query = ge_filter.search_input.text().strip().casefold()
        selected_name = str(ge_state.get("selected_item_name", ""))
        side = str(ge_side.currentData() or "buy")
        editing = ge_state.get("editing_order_id") is not None
        ge_item_list.blockSignals(True)
        ge_item_list.clear()
        selected_widget_item = None
        for row in ge_state["projection"].get("items", ()):
            if (
                side == "sell"
                and int(row.get("owned", 0) or 0) <= 0
                and not (editing and row.get("item_name") == selected_name)
            ):
                continue
            haystack = f"{row.get('item_name', '')} {row.get('category', '')}".casefold()
            if query and query not in haystack:
                continue
            owned = int(row.get("owned", 0) or 0)
            item = QListWidgetItem(
                f"{row['item_name']}  ·  "
                f"{int(row.get('guide_price', 0) or 0):,} Coins"
                # Bare x{n} matches how the Bank tab renders quantities. Hidden
                # at zero so the buy catalog is not a wall of "x0".
                + (f"  ·  x{owned}" if owned else "")
            )
            item.setData(Qt.ItemDataRole.UserRole, dict(row))
            icon_path = str(row.get("asset_path") or "")
            if icon_path and os.path.exists(icon_path):
                item.setIcon(QIcon(icon_path))
            ge_item_list.addItem(item)
            if row.get("item_name") == selected_name:
                selected_widget_item = item
        if ge_item_list.count() == 0:
            if query:
                empty_text = "No exchangeable items match your search."
            elif side == "sell":
                empty_text = "You own nothing exchangeable to sell."
            else:
                empty_text = "No exchangeable items are available."
            empty = QListWidgetItem(empty_text)
            empty.setFlags(Qt.ItemFlag.NoItemFlags)
            ge_item_list.addItem(empty)
        elif selected_widget_item is not None:
            ge_item_list.setCurrentItem(selected_widget_item)
        ge_item_list.blockSignals(False)

    def _populate_ge_fill_log() -> None:
        entries = tuple(ge_state["projection"].get("fill_log", ()) or ())
        answered_cards = int(ge_state["projection"].get("answered_cards", 0) or 0)
        ge_log_toggle.setText(f"Recent fills ({len(entries)})")
        ge_log_list.clear()
        if not entries:
            empty = QListWidgetItem("No fills yet — place an offer and answer cards.")
            empty.setFlags(Qt.ItemFlag.NoItemFlags)
            empty.setForeground(dim_text_color(ge_log_list))
            ge_log_list.addItem(empty)
            return
        base = ge_log_list.palette().color(QPalette.ColorRole.Base)
        light = base.lightness() > 128
        done_color = QColor("#3f6e1e" if light else "#85c54b")
        partial_color = QColor("#8a6100" if light else "#e0b341")
        for entry in entries:
            delta = answered_cards - int(entry.get("card", 0) or 0)
            when = (
                "Now"
                if delta <= 0
                else f"{delta} card ago"
                if delta == 1
                else f"{delta} cards ago"
            )
            done = int(entry.get("completed_quantity", 0) or 0)
            total = int(entry.get("original_quantity", 0) or 0)
            verb = "sold" if str(entry.get("side")) == "sell" else "bought"
            row = QListWidgetItem(
                f"{when}: {entry.get('item_name')} - {done}/{total} {verb}"
            )
            row.setFlags(Qt.ItemFlag.NoItemFlags)
            row.setForeground(done_color if done >= total else partial_color)
            ge_log_list.addItem(row)

    def _selected_ge_order():
        selected_id = ge_state.get("selected_order_id")
        for order in ge_state["projection"].get("slots", ()):
            if isinstance(order, dict) and order.get("id") == selected_id:
                return order
        return None

    def _refresh_ge(projection=None, message="") -> None:
        if isinstance(projection, dict):
            ge_state["projection"] = projection
        elif callable(get_ge_projection):
            try:
                fetched = get_ge_projection()
                if isinstance(fetched, dict):
                    ge_state["projection"] = fetched
            except Exception:
                pass
        projection = ge_state["projection"]
        locked = bool(projection.get("ironman_mode"))
        ge_balance.setText(f"{int(projection.get('coins', 0) or 0):,} Coins")
        settings = projection.get("settings", {}) or {}
        ge_high_value.setValue(
            max(int(settings.get("high_value_confirmation", 1_000_000) or 1), 1)
        )
        ge_low_price.setValue(
            max(
                1,
                min(
                    100,
                    int(
                        round(
                            float(settings.get("low_price_multiplier", 0.1) or 0.1)
                            * 100
                        )
                    ),
                ),
            )
        )
        ge_high_price.setValue(
            max(
                1,
                min(
                    100,
                    int(round(float(settings.get("high_price_multiplier", 10.0) or 10.0))),
                ),
            )
        )
        ge_ironman.blockSignals(True)
        ge_ironman.setChecked(locked)
        ge_ironman.blockSignals(False)
        ge_catalog_shell.setEnabled(not locked and callable(on_ge_action))
        ge_editor.setEnabled(not locked and callable(on_ge_action))
        slots = tuple(projection.get("slots", ()))
        occupied_ids = set()
        has_collectible = False
        for index, button in enumerate(ge_slot_buttons):
            order = slots[index] if index < len(slots) else None
            if not isinstance(order, dict):
                button.setText(f"Slot {index + 1}\nEmpty offer")
                button.setIcon(QIcon())
                button.setProperty("geOrderId", None)
                button.setChecked(False)
                continue
            order_id = int(order.get("id", 0) or 0)
            occupied_ids.add(order_id)
            side = str(order.get("side", "")).upper()
            item_name = str(order.get("item_name", ""))
            complete = int(order.get("completed_quantity", 0) or 0)
            original = int(order.get("original_quantity", 0) or 0)
            button.setText(
                f"{side} · {item_name}\n{complete:,}/{original:,} filled · {str(order.get('status', '')).title()}"
            )
            button.setProperty("geOrderId", order_id)
            button.setChecked(order_id == ge_state.get("selected_order_id"))
            item_row = next(
                (
                    row
                    for row in projection.get("items", ())
                    if row.get("item_name") == item_name
                ),
                None,
            )
            icon_path = str((item_row or {}).get("asset_path") or "")
            button.setIcon(QIcon(icon_path) if icon_path and os.path.exists(icon_path) else QIcon())
            has_collectible = has_collectible or bool(
                int(order.get("collectible_coins", 0) or 0)
                or int(order.get("collectible_items", 0) or 0)
            )
        if ge_state.get("selected_order_id") not in occupied_ids:
            ge_state["selected_order_id"] = None
            ge_state["editing_order_id"] = None
        order = _selected_ge_order()
        if order is None:
            ge_order_detail.setText("Select an occupied slot to collect or cancel.")
            ge_collect.setEnabled(False)
            ge_edit.setEnabled(False)
            ge_cancel.setEnabled(False)
        else:
            collectible_coins = int(order.get("collectible_coins", 0) or 0)
            collectible_items = int(order.get("collectible_items", 0) or 0)
            collect_parts = []
            if collectible_items:
                collect_parts.append(
                    f"{collectible_items:,} × {order.get('item_name')}"
                )
            if collectible_coins:
                collect_parts.append(f"{collectible_coins:,} Coins")
            collect_text = (
                "Collect " + " and ".join(collect_parts)
                if collect_parts
                else "Nothing ready to collect"
            )
            ge_order_detail.setText(
                f"{str(order.get('side', '')).title()} {order.get('item_name')} · "
                f"{int(order.get('completed_quantity', 0) or 0):,}/"
                f"{int(order.get('original_quantity', 0) or 0):,} filled · "
                f"{int(order.get('remaining_quantity', 0) or 0):,} remaining · "
                f"{collect_text}"
            )
            ge_collect.setEnabled(bool(collectible_coins or collectible_items))
            ge_edit.setEnabled(str(order.get("status")) in {"open", "partial"})
            ge_cancel.setEnabled(str(order.get("status")) in {"open", "partial"})
            if (
                ge_state.get("editing_order_id") == order.get("id")
                and str(order.get("status")) not in {"open", "partial"}
            ):
                ge_state["editing_order_id"] = None
        ge_collect_all.setEnabled(has_collectible and callable(on_ge_action))
        _populate_ge_items()
        _populate_ge_fill_log()
        _refresh_ge_preview()
        if message:
            ge_status.setStyleSheet(f"color: {dim_text_css(ge_status)};")
            ge_status.setText(message)
        elif locked:
            ge_status.setStyleSheet(f"color: {dim_text_css(ge_status)};")
            ge_status.setText(
                str(projection.get("lock_reason") or "Grand Exchange is disabled in Ironman mode.")
            )
        elif projection.get("has_collectible"):
            ge_status.setStyleSheet("color: palette(text); font-weight: 600;")
            ge_status.setText("Offer proceeds ready to collect.")
        else:
            ge_status.setStyleSheet(f"color: {dim_text_css(ge_status)};")
            ge_status.setText("Offers advance once per answered card. Bankstanding does not accelerate them.")

    def _run_ge_action(action_id, payload):
        if not callable(on_ge_action):
            return {"ok": False, "reason": "unavailable"}
        try:
            result = on_ge_action(action_id, payload)
        except Exception as exc:
            result = {"ok": False, "message": str(exc)}
        if not isinstance(result, dict):
            result = {"ok": bool(result)}
        if not result.get("ok"):
            message = _ge_reason_message(result)
        elif action_id == "set_ironman":
            message = (
                str((result.get("projection") or {}).get("lock_reason") or "")
                if bool(payload.get("enabled"))
                else "Grand Exchange access enabled."
            )
        else:
            message = {
                "place_offer": "Offer placed.",
                "edit_offer": "Offer updated; queue age reset.",
                "cancel_offer": "Offer cancelled; escrow is ready to collect.",
                "collect_offer": "Offer proceeds collected.",
                "collect_all": "All available offer proceeds collected.",
                "set_offer_safety": "Grand Exchange offer safety updated.",
            }.get(action_id, "")
        _refresh_ge(result.get("projection"), message)
        return result

    def _on_ge_item_selected(current, _previous=None) -> None:
        row = current.data(Qt.ItemDataRole.UserRole) if current is not None else None
        if not isinstance(row, dict):
            return
        ge_state["selected_item_name"] = str(row.get("item_name", ""))
        ge_state["selected_order_id"] = None
        ge_state["editing_order_id"] = None
        guide = max(int(row.get("guide_price", 1) or 1), 1)
        ge_price.setValue(guide)
        ge_quantity.setValue(1)
        _refresh_ge(ge_state["projection"])

    def _on_ge_side_changed(_index=0) -> None:
        if ge_state.get("editing_order_id") is not None:
            _refresh_ge_preview()
            return
        if str(ge_side.currentData() or "buy") == "sell":
            row = _ge_current_item()
            if row is not None and int(row.get("owned", 0) or 0) <= 0:
                ge_state["selected_item_name"] = ""
        _populate_ge_items()
        _refresh_ge_preview()

    def _on_ge_slot_clicked(index) -> None:
        slots = tuple(ge_state["projection"].get("slots", ()))
        order = slots[index] if index < len(slots) else None
        ge_state["selected_order_id"] = (
            int(order.get("id", 0) or 0)
            if isinstance(order, dict)
            else None
        )
        ge_state["editing_order_id"] = None
        if isinstance(order, dict):
            ge_state["selected_item_name"] = str(order.get("item_name", ""))
        _refresh_ge(ge_state["projection"])
        if not isinstance(order, dict):
            ge_filter.search_input.setFocus()

    def _fill_ge_quantity_with_all() -> None:
        row = _ge_current_item()
        if row is None:
            return
        available = max(int(row.get("owned", 0) or 0), 0)
        editing_order = _selected_ge_order()
        if (
            editing_order is not None
            and editing_order.get("id") == ge_state.get("editing_order_id")
            and str(editing_order.get("side")) == "sell"
        ):
            # Escrowed items are already out of the bank, so the editable
            # ceiling is what is still held plus what this offer holds.
            available += int(editing_order.get("escrow_items", 0) or 0)
        ge_quantity.setValue(max(1, available))

    def _set_ge_quick_price(percent) -> None:
        row = _ge_current_item()
        if row is None:
            return
        if percent is None:
            ge_price.setValue(max(int(row.get("guide_price", 1) or 1), 1))
            return
        # Exactly the period client script (interface 105 -> script 4112),
        # recovered by disassembling rev 727 and byte-identical across all six
        # pre-EOC builds. See source-audits/ge-offer-price-controls-2026-07-24.md.
        # It compounds off the displayed price, truncates toward zero, and only
        # forces a one-coin step when truncation would have moved nothing —
        # which is why "-5%" on 20 gp gives 19 rather than sticking.
        price = max(int(ge_price.value()), 1)
        percent = int(percent)
        if percent > 100 and price > _GE_PRICE_OVERFLOW_LIMIT:
            stepped = _GE_PRICE_CEILING
        elif percent < 100 and price <= 1:
            stepped = 1
        else:
            stepped = (price * percent) // 100
            if stepped == price:
                stepped += 1 if percent >= 100 else -1
        ge_price.setValue(max(1, stepped))

    def _submit_ge_offer() -> None:
        row = _ge_current_item()
        if row is None:
            return
        editing_order = _selected_ge_order()
        if (
            editing_order is not None
            and editing_order.get("id") == ge_state.get("editing_order_id")
        ):
            payload = {
                "order_id": int(editing_order["id"]),
                "remaining_quantity": int(ge_quantity.value()),
                "unit_price": int(ge_price.value()),
            }
            result = _run_ge_action("edit_offer", payload)
            if (
                not result.get("ok")
                and result.get("reason") == "confirmation_required"
            ):
                answer = QMessageBox.question(
                    dialog,
                    "Confirm Grand Exchange edit",
                    (
                        f"Update this offer to {payload['remaining_quantity']:,} "
                        f"remaining at {payload['unit_price']:,} Coins each?"
                    ),
                    QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                    QMessageBox.StandardButton.No,
                )
                if answer == QMessageBox.StandardButton.Yes:
                    payload["confirmed"] = True
                    result = _run_ge_action("edit_offer", payload)
            if result.get("ok"):
                ge_state["editing_order_id"] = None
                _refresh_ge(result.get("projection"), "Offer updated; queue age reset.")
            return
        payload = {
            "side": str(ge_side.currentData() or "buy"),
            "item_name": str(row["item_name"]),
            "quantity": int(ge_quantity.value()),
            "unit_price": int(ge_price.value()),
        }
        preview = _run_ge_action("preview_offer", payload)
        if not preview.get("ok"):
            return
        if preview.get("confirmation_required"):
            answer = QMessageBox.question(
                dialog,
                "Confirm Grand Exchange offer",
                (
                    f"Place this {payload['side']} offer for "
                    f"{payload['quantity']:,} × {payload['unit_price']:,} Coins "
                    f"({int(preview.get('total_value', 0) or 0):,} Coins total)?"
                ),
                QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No,
            )
            if answer != QMessageBox.StandardButton.Yes:
                ge_status.setText("Offer not placed.")
                return
            payload["confirmed"] = True
        result = _run_ge_action("place_offer", payload)
        if result.get("ok"):
            ge_state["selected_order_id"] = int(
                (result.get("order") or {}).get("id", 0) or 0
            )
            _refresh_ge(result.get("projection"), "Offer placed.")

    def _begin_edit_selected_ge_offer() -> None:
        order = _selected_ge_order()
        if order is None or str(order.get("status")) not in {"open", "partial"}:
            return
        ge_state["editing_order_id"] = int(order["id"])
        ge_state["selected_item_name"] = str(order["item_name"])
        side_index = ge_side.findData(str(order["side"]))
        if side_index >= 0:
            ge_side.setCurrentIndex(side_index)
        ge_quantity.setValue(max(int(order.get("remaining_quantity", 1) or 1), 1))
        ge_price.setValue(max(int(order.get("submitted_unit_price", 1) or 1), 1))
        _populate_ge_items()
        _refresh_ge_preview()

    def _collect_selected_ge_offer() -> None:
        order = _selected_ge_order()
        if order is not None:
            _run_ge_action("collect_offer", {"order_id": int(order["id"])})

    def _cancel_selected_ge_offer() -> None:
        order = _selected_ge_order()
        if order is not None:
            _run_ge_action("cancel_offer", {"order_id": int(order["id"])})

    def _toggle_ge_ironman(checked=False) -> None:
        result = _run_ge_action("set_ironman", {"enabled": bool(checked)})
        if not result.get("ok"):
            ge_ironman.blockSignals(True)
            ge_ironman.setChecked(
                bool(ge_state["projection"].get("ironman_mode"))
            )
            ge_ironman.blockSignals(False)

    def _apply_ge_offer_safety() -> None:
        _run_ge_action(
            "set_offer_safety",
            {
                "high_value_confirmation": int(ge_high_value.value()),
                "low_price_percent": int(ge_low_price.value()),
                "high_price_multiplier": int(ge_high_price.value()),
            },
        )

    ge_filter.search_input.textChanged.connect(lambda _text="": _populate_ge_items())
    ge_item_list.currentItemChanged.connect(_on_ge_item_selected)
    ge_side.currentIndexChanged.connect(_on_ge_side_changed)
    ge_quantity.valueChanged.connect(lambda _value=1: _refresh_ge_preview())
    ge_price.valueChanged.connect(lambda _value=1: _refresh_ge_preview())
    for factor, button in ge_price_buttons.items():
        button.clicked.connect(
            lambda _checked=False, price_factor=factor: _set_ge_quick_price(price_factor)
        )
    for index, button in enumerate(ge_slot_buttons):
        button.clicked.connect(
            lambda _checked=False, slot_index=index: _on_ge_slot_clicked(slot_index)
        )
    ge_sell_all.clicked.connect(lambda _checked=False: _fill_ge_quantity_with_all())
    ge_submit.clicked.connect(lambda _checked=False: _submit_ge_offer())
    ge_collect.clicked.connect(lambda _checked=False: _collect_selected_ge_offer())
    ge_edit.clicked.connect(lambda _checked=False: _begin_edit_selected_ge_offer())
    ge_cancel.clicked.connect(lambda _checked=False: _cancel_selected_ge_offer())
    ge_collect_all.clicked.connect(
        lambda _checked=False: _run_ge_action("collect_all", {})
    )
    ge_ironman.toggled.connect(_toggle_ge_ironman)
    ge_apply_safety.clicked.connect(
        lambda _checked=False: _apply_ge_offer_safety()
    )
    ge_safety_toggle.toggled.connect(
        lambda expanded=False: (
            ge_safety_toggle.setArrowType(
                Qt.ArrowType.DownArrow
                if expanded
                else Qt.ArrowType.RightArrow
            ),
            ge_safety_panel.setVisible(bool(expanded)),
        )
    )
    ge_log_toggle.toggled.connect(
        lambda expanded=False: (
            ge_log_toggle.setArrowType(
                Qt.ArrowType.DownArrow
                if expanded
                else Qt.ArrowType.RightArrow
            ),
            ge_log_list.setVisible(bool(expanded)),
        )
    )

    _refresh_ge()
    tabs.addTab(ge_tab, "Grand Exchange")
    _set_global_tab_icon(ge_tab, "grand_exchange_icon.png")
    tabs.setTabToolTip(
        tabs.indexOf(ge_tab),
        "Place and manage review-paced Grand Exchange offers",
    )

    _add_deferred_tab(
        "Quests",
        "quest_icon.png",
        "View quest journals and active quest progress",
        build_quests_tab,
    )

    # Stats tab (period-style three-column skill grid + selected detail)
    stats_tab = QWidget()
    st_layout = QVBoxLayout(stats_tab)
    st_layout.setContentsMargins(12, 12, 12, 12)
    st_layout.setSpacing(8)

    stats_body = QWidget()
    stats_body_layout = QHBoxLayout(stats_body)
    stats_body_layout.setContentsMargins(0, 0, 0, 0)
    stats_body_layout.setSpacing(12)

    # The 2012 Stats interface uses a fixed three-column order. Keep that
    # familiar scan pattern while letting Qt provide native focus, selection,
    # tooltips, and short-window scrolling.
    stats_skill_order = (
        "Attack", "Constitution", "Mining",
        "Strength", "Agility", "Smithing",
        "Defence", "Herblore", "Fishing",
        "Ranged", "Thieving", "Cooking",
        "Prayer", "Crafting", "Firemaking",
        "Magic", "Fletching", "Woodcutting",
        "Runecrafting", "Slayer", "Farming",
        "Construction", "Hunter", "Summoning",
        "Dungeoneering",
    )
    selector = QWidget()
    selector.setObjectName("statsSkillGrid")
    sel_layout = QGridLayout(selector)
    sel_layout.setHorizontalSpacing(4)
    sel_layout.setVerticalSpacing(2)
    sel_layout.setContentsMargins(8, 8, 8, 8)
    for column in range(3):
        sel_layout.setColumnStretch(column, 1)

    _stats_skill_defs = {
        name: get_skill(name)
        for name in stats_skill_order
    }

    def _stats_current_level(
        skill_name: str,
        skill_def: Any,
        base_level: int,
    ) -> int:
        current_level = base_level
        current_levels = player_data.get("combat_current_levels", {}) or {}
        skill_id = (
            skill_def.id
            if skill_def is not None
            else skill_name.lower()
        )
        if isinstance(current_levels, Mapping):
            try:
                current_level = max(
                    1,
                    int(current_levels.get(skill_id, base_level)),
                )
            except (TypeError, ValueError):
                current_level = base_level
        if skill_id == "agility":
            current_level = max(
                current_level,
                agility_effective_level_pure(player_data),
            )
        return current_level

    # Helper to create a details panel for a specific skill
    def _mk_skill_details(skill_name: str) -> QWidget:
        block = QWidget()
        b_layout = QVBoxLayout(block)
        b_layout.setContentsMargins(0, 0, 0, 0)
        b_layout.setSpacing(8)
        title_row = QHBoxLayout()
        title_row.setSpacing(8)
        icon_path = skill_icon_path_for(skill_name)
        if icon_path and os.path.exists(icon_path):
            title_icon = QLabel()
            title_icon.setObjectName("statsSelectedSkillIcon")
            title_icon.setFixedSize(40, 40)
            title_icon.setPixmap(
                QPixmap(icon_path).scaled(
                    36,
                    36,
                    Qt.AspectRatioMode.KeepAspectRatio,
                    Qt.TransformationMode.FastTransformation,
                )
            )
            title_row.addWidget(title_icon)
        title = QLabel(f"{skill_name} Stats")
        title.setObjectName("statsSelectedSkillTitle")
        title.setStyleSheet("font-size: 16px; font-weight: bold;")
        title_row.addWidget(title)
        title_row.addStretch(1)
        b_layout.addLayout(title_row)
        metrics = QWidget()
        metrics.setObjectName("statsSkillMetrics")
        metrics.setMaximumWidth(520)
        grid = QGridLayout(metrics)
        grid.setContentsMargins(0, 0, 0, 0)
        grid.setHorizontalSpacing(12)
        grid.setVerticalSpacing(8)
        grid.setColumnStretch(1, 1)
        skill_def = _stats_skill_defs.get(skill_name)
        level_key = skill_def.level_key if skill_def is not None else f"{skill_name.lower()}_level"
        exp_key = skill_def.exp_key if skill_def is not None else f"{skill_name.lower()}_exp"
        level = int(player_data.get(level_key, 1) or 1)
        current_level = _stats_current_level(
            skill_name,
            skill_def,
            level,
        )
        exp = round(player_data.get(exp_key, 0), 1)
        exp_text = (
            f"{int(exp):,}"
            if float(exp).is_integer()
            else f"{exp:,.1f}"
        )
        grid.addWidget(QLabel("Current / Base Level:"), 0, 0)
        grid.addWidget(QLabel(f"{current_level} / {level}"), 0, 1)
        grid.addWidget(QLabel("Total Experience:"), 1, 0)
        grid.addWidget(QLabel(exp_text), 1, 1)
        if level < 99:
            exp_to_next = round(max(0, EXP_TABLE[level] - exp), 1)
            exp_to_next_text = (
                f"{int(exp_to_next):,}"
                if float(exp_to_next).is_integer()
                else f"{exp_to_next:,.1f}"
            )
            grid.addWidget(QLabel("Experience to Next Level:"), 2, 0)
            grid.addWidget(QLabel(exp_to_next_text), 2, 1)
        prog = QProgressBar()
        prog.setObjectName("statsSkillProgress")
        prog.setMinimumWidth(240)
        prog.setMaximumWidth(320)
        try:
            progress_percentage = (exp - EXP_TABLE[level - 1]) / (EXP_TABLE[level] - EXP_TABLE[level - 1]) * 100
            prog.setValue(int(max(0, min(100, progress_percentage))))
        except Exception:
            prog.setValue(0)
        grid.addWidget(QLabel("Level Progress:"), 3, 0)
        grid.addWidget(prog, 3, 1)
        b_layout.addWidget(
            metrics,
            0,
            Qt.AlignmentFlag.AlignLeft,
        )
        return block

    # Details container (will switch based on selected skill)
    details_container = QWidget()
    details_layout = QVBoxLayout(details_container)
    details_layout.setContentsMargins(0, 0, 0, 0)

    # The registry remains authoritative for save keys. The period ordering
    # intentionally includes Combat's separately tracked component skills and
    # Dungeoneering's existing stat row even before its training surface ships.
    _stats_fallback = os.path.join(current_dir, "icon", "stats_icon.png")
    skills_info = [
        (
            name,
            skill_icon_path_for(name) or _stats_fallback,
        )
        for name in stats_skill_order
    ]

    # Import here to keep headless safety for static analyzers
    try:
        from aqt.qt import QToolButton as StatsToolButton  # type: ignore
    except Exception:
        StatsToolButton = QPushButton  # fallback for typing

    button_group = QButtonGroup()
    button_group.setExclusive(True)
    buttons = {}
    for idx, (name, icon_path) in enumerate(skills_info):
        skill_def = _stats_skill_defs.get(name)
        level_key = (
            skill_def.level_key
            if skill_def is not None
            else f"{name.lower()}_level"
        )
        exp_key = (
            skill_def.exp_key
            if skill_def is not None
            else f"{name.lower()}_exp"
        )
        level = int(player_data.get(level_key, 1) or 1)
        exp = float(player_data.get(exp_key, 0) or 0)
        current_level = _stats_current_level(name, skill_def, level)
        btn = StatsToolButton()
        btn.setObjectName(
            f"statsSkillButton_{skill_def.id if skill_def else name.lower()}"
        )
        btn.setCheckable(True)
        btn.setToolTip(
            f"{name} — current {current_level} / base {level} — {exp:,.0f} XP"
        )
        btn.setAccessibleName(
            f"{name}, current level {current_level}, base level {level}"
        )
        if os.path.exists(icon_path):
            btn.setIcon(
                QIcon(
                    QPixmap(icon_path).scaled(
                        24,
                        24,
                        Qt.AspectRatioMode.KeepAspectRatio,
                        Qt.TransformationMode.FastTransformation,
                    )
                )
            )
        btn.setText(f"{current_level} / {level}")
        if hasattr(btn, "setToolButtonStyle"):
            try:
                btn.setToolButtonStyle(Qt.ToolButtonStyle.ToolButtonTextBesideIcon)  # type: ignore[attr-defined]
            except Exception:
                pass
        btn.setIconSize(QSize(24, 24))
        btn.setFixedHeight(38)
        btn.setSizePolicy(
            QSizePolicy.Policy.Expanding,
            QSizePolicy.Policy.Fixed,
        )
        btn.setAutoRaise(True)
        btn.setStyleSheet(
            """
            QToolButton {
                border: 1px solid palette(mid);
                border-radius: 4px;
                padding: 2px 6px;
                color: palette(text);
                background: palette(base);
                font-weight: 600;
            }
            QToolButton:hover { border-color: palette(dark); }
            QToolButton:checked {
                border: 2px solid #4CAF50;
                color: palette(text);
                background: rgba(76, 175, 80, 0.18);
            }
            """
        )
        button_group.addButton(btn, idx)
        row, column = divmod(idx, 3)
        sel_layout.addWidget(btn, row, column)
        buttons[name] = btn
        # Connect per-button click to select and persist
        btn.clicked.connect(lambda _checked=False, n=name: (
            _select_skill(n),
            (mw and getattr(mw, 'col', None) and mw.col.set_config("ankiscape_stats_selected_skill", n))
        ))

    total_level = sum(
        int(
            player_data.get(
                skill_def.level_key if skill_def is not None else "",
                1,
            )
            or 1
        )
        for skill_def in _stats_skill_defs.values()
    )
    total_level_label = QLabel(f"Total level: {total_level:,}")
    total_level_label.setObjectName("statsTotalLevel")
    total_level_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
    total_level_label.setStyleSheet(
        "font-weight: 700; color: palette(text); padding: 4px;"
    )
    final_row = (len(skills_info) + 2) // 3
    sel_layout.addWidget(total_level_label, final_row, 0, 1, 3)
    sel_layout.setRowStretch(final_row + 1, 1)

    selector_scroll = QScrollArea()
    selector_scroll.setObjectName("statsSkillSelectorScroll")
    selector_scroll.setFrameShape(QtFrame.Shape.NoFrame)
    selector_scroll.setWidgetResizable(True)
    selector_scroll.setHorizontalScrollBarPolicy(
        Qt.ScrollBarPolicy.ScrollBarAlwaysOff
    )
    selector_scroll.setVerticalScrollBarPolicy(
        Qt.ScrollBarPolicy.ScrollBarAsNeeded
    )
    selector_scroll.setWidget(selector)
    selector_scroll.setFixedWidth(344)
    stats_body_layout.addWidget(selector_scroll)
    stats_body_layout.addWidget(details_container, 1)

    # Update details when a skill is selected
    def _select_skill(skill_name: str):
        # Clear previous content. hide()+setParent(None) before deleteLater so
        # the old details block is removed from view immediately; deleteLater
        # alone is async and would briefly overlap the new block.
        child = details_layout.takeAt(0)
        while child:
            w = child.widget()
            if w is not None:
                w.hide()
                w.setParent(None)
                w.deleteLater()
            child = details_layout.takeAt(0)
        # Add new details
        details_layout.addWidget(_mk_skill_details(skill_name))
        details_layout.addStretch(1)

    # No idClicked usage; handled per-button above

    # Initial selection
    # Load persisted selection if available; fall back to current_skill then Mining
    persisted = None
    try:
        if mw and getattr(mw, 'col', None):
            persisted = mw.col.get_config("ankiscape_stats_selected_skill", None)
    except Exception:
        persisted = None
    initial_skill = persisted if persisted in {n for n, _ in skills_info} else (current_skill if current_skill in {n for n, _ in skills_info} else "Mining")
    initial_index = next((i for i, (n, _) in enumerate(skills_info) if n == initial_skill), 0)
    button_group.button(initial_index).setChecked(True)
    _select_skill(initial_skill)

    st_layout.addWidget(stats_body, 1)
    # Defer adding Stats tab until after Bank to satisfy desired ordering (Bank then Stats)
    ach_icon_path = os.path.join(current_dir, "icon", "achievement_icon.png")

    # Achievements tab
    # Bank tab (all inventory items)
    bank_tab = QWidget()
    bk_layout = QVBoxLayout(bank_tab)
    bk_layout.setContentsMargins(12, 12, 12, 12)
    bk_layout.setSpacing(8)

    # Carried inventory overlay — the 28-slot pack the review loop draws from and
    # banks when full. Collapsible header. Casual packing is inferred (even split
    # for processing, action-filled for gathering) with approximate bank runs;
    # players who want to tune it use the advanced 4x7 grid below.
    def _carried_panel_summary_text() -> str:
        carried = player_data.get("carried_inventory") or {}
        run = player_data.get("skilling_bank_run") or {}
        total_slots = 0
        carried_targets = 0
        for view in carried.values():
            if isinstance(view, dict) and view:
                total_slots += inventory_pure.carried_slots_used(view, carried_stackable_names)
                carried_targets += 1
        if run:
            status = f"Banking… {int(run.get('reviews_remaining', 0))} review(s) left"
        elif total_slots:
            status = f"{total_slots} slot(s) held across {carried_targets} target(s)"
        else:
            status = "Pack empty — nothing carried yet"
        return (
            f"{status}. The pack fills to {inventory_pure.CARRIED_CAPACITY} slots "
            "as you gather or process, then a bank run costs one review."
        )

    carried_header = QPushButton("▸  Carried inventory")
    carried_header.setObjectName("carriedInventoryHeader")
    carried_header.setCheckable(True)
    carried_header.setChecked(False)
    carried_header.setStyleSheet("QPushButton { text-align: left; font-weight: 600; border: none; padding: 4px 2px; }")

    carried_body = QWidget()
    carried_body.setVisible(False)
    cb_layout = QVBoxLayout(carried_body)
    cb_layout.setContentsMargins(10, 2, 4, 6)
    cb_layout.setSpacing(6)

    # Keep/Drop toggle — only meaningful for a gathering target (power-gather =
    # drop the product for the fastest XP, no banking). Absent otherwise.
    if carried_keep_drop_state is not None:
        keep_drop_check = QCheckBox("Drop gathered products (power-gather, no banking)")
        keep_drop_check.setObjectName("carriedKeepDropCheck")
        keep_drop_check.setChecked(carried_keep_drop_state == "drop")
        if on_set_carried_keep_drop is not None:
            keep_drop_check.toggled.connect(lambda checked: on_set_carried_keep_drop(bool(checked)))
        cb_layout.addWidget(keep_drop_check)

    # Carried-pack section — one control with two mutually-exclusive views of the
    # same 28 slots, switched by an Auto | Custom pill:
    #   * Auto   — pick a supply mode (Balanced/Max output/Max safety); the game
    #              auto-fills food + stat potions and refills them at bank runs.
    #   * Custom — hand-arrange an exact {item: count} 28-slot layout the game
    #              refills verbatim.
    # The same section is built on both the Equipment and Bank tabs, so the
    # registries below keep every instance in sync: one grid refresher per section
    # repaints its own 28 cells, one switch setter per section reflects the
    # advanced flag without re-firing the backend, and one auto-view refresher per
    # section keeps its supply summary + bank-run text (and pack-mode combo)
    # current. carried_mode_state is the single source of truth the bank context
    # menu reads to decide whether "Set carried quantity" applies.
    carried_grid_refreshers: list = []
    carried_switch_setters: list = []
    carried_section_refreshers: list = []
    carried_mode_state = {"advanced": bool(carried_advanced_state)}
    _dim_cell = dim_text_css(carried_body)
    _CARRIED_CELL_FILLED_CSS = (
        "QPushButton { border: 1px solid palette(mid); border-radius: 4px; "
        "background: transparent; color: palette(text); font-size: 9px; padding: 2px; }"
        "QPushButton:hover { border: 1px solid palette(highlight); }"
    )
    _CARRIED_CELL_EMPTY_CSS = (
        "QPushButton { border: 1px dashed palette(mid); border-radius: 4px; "
        "background: transparent; color: " + _dim_cell + "; font-size: 9px; }"
        "QPushButton:hover { border: 1px solid palette(highlight); }"
    )

    def _refresh_carried_layout_grid() -> None:
        for _refresh in carried_grid_refreshers:
            _refresh()

    def _refresh_carried_sections() -> None:
        for _refresh in carried_section_refreshers:
            _refresh()

    def _pack_pickable_items() -> list:
        """Distinct bank item names offered by the empty-slot picker."""
        inv = player_data.get("inventory", {}) or {}
        names: list = []
        for _label, rows in grouped_inventory(inv):
            for name, _amount, _asset in rows:
                if name and name not in names:
                    names.append(name)
        return names

    def _current_layout_quantity(item_name: str) -> int:
        if get_carried_layout_cells is None:
            return 0
        return sum(
            int(count)
            for name, count in get_carried_layout_cells()
            if name == item_name
        )

    def _prompt_set_pack_quantity(item_name: str, parent=None) -> None:
        """Set one absolute custom-pack quantity, preserving its queue position."""
        if on_set_carried_layout_quantity is None:
            return
        current = _current_layout_quantity(item_name)
        maximum = 2_147_483_647 if item_name in carried_stackable_names else inventory_pure.CARRIED_CAPACITY
        quantity, ok = QInputDialog.getInt(
            parent or dialog,
            "Set carried quantity",
            f"{item_name} quantity:",
            min(maximum, current if current > 0 else 1),
            0,
            maximum,
            1,
        )
        if not ok:
            return
        accepted = on_set_carried_layout_quantity(item_name, quantity)
        if accepted is False:
            QMessageBox.information(
                parent or dialog,
                "Carried pack full",
                "That quantity would exceed the 28-slot carried pack.",
            )
            return
        _refresh_carried_layout_grid()

    def _prompt_add_to_pack() -> None:
        """Empty-slot click: pick a Bank item, then set its desired quantity."""
        if on_set_carried_layout_quantity is None:
            return
        names = _pack_pickable_items()
        if not names:
            QMessageBox.information(dialog, "Carried pack", "Your bank is empty — nothing to add.")
            return
        choice, ok = QInputDialog.getItem(dialog, "Add to carried pack", "Item:", names, 0, False)
        if ok and choice:
            _prompt_set_pack_quantity(str(choice), dialog)

    def _sync_carried_switches(advanced: bool) -> None:
        carried_mode_state["advanced"] = bool(advanced)
        for setter in carried_switch_setters:
            setter(bool(advanced))

    def _build_carried_pack_section(primary: bool) -> QWidget:
        """One carried-pack control (Auto | Custom pill + both views).

        Built on both the Equipment and Bank tabs; `primary` (Equipment) carries
        the canonical object names the tests query, while the secondary instance
        suffixes "Bank" so every object name stays unique in the widget tree.
        """
        name_suffix = "" if primary else "Bank"
        container = QWidget()
        section_layout = QVBoxLayout(container)
        section_layout.setContentsMargins(0, 0, 0, 0)
        section_layout.setSpacing(6)

        # --- Auto | Custom segmented switch ---
        def _switch_css(side: str, active: bool) -> str:
            radius = (
                "border-top-left-radius:6px;border-bottom-left-radius:6px;border-right:none;"
                if side == "left"
                else "border-top-right-radius:6px;border-bottom-right-radius:6px;"
            )
            if active:
                face = "background:palette(highlight);color:palette(highlighted-text);font-weight:600;"
            else:
                face = f"background:transparent;color:{dim_text_css(container)};"
            return f"QPushButton{{border:1px solid palette(mid);{radius}padding:3px 18px;font-size:11px;{face}}}"

        auto_btn = QPushButton("Auto")
        auto_btn.setObjectName(f"carriedModeAuto{name_suffix}")
        auto_btn.setCheckable(True)
        custom_btn = QPushButton("Custom")
        custom_btn.setObjectName(f"carriedModeCustom{name_suffix}")
        custom_btn.setCheckable(True)

        auto_view = QWidget()
        custom_view = QWidget()

        def _apply_mode(advanced: bool) -> None:
            auto_btn.setChecked(not advanced)
            custom_btn.setChecked(advanced)
            auto_btn.setStyleSheet(_switch_css("left", not advanced))
            custom_btn.setStyleSheet(_switch_css("right", advanced))
            auto_view.setVisible(not advanced)
            custom_view.setVisible(advanced)

        carried_switch_setters.append(_apply_mode)

        def _on_switch(advanced: bool) -> None:
            _apply_mode(bool(advanced))
            if on_set_carried_advanced is not None:
                on_set_carried_advanced(bool(advanced))
            _sync_carried_switches(bool(advanced))

        auto_btn.clicked.connect(lambda _c=False: _on_switch(False))
        custom_btn.clicked.connect(lambda _c=False: _on_switch(True))

        switch_row = QWidget()
        switch_layout = QHBoxLayout(switch_row)
        switch_layout.setContentsMargins(0, 0, 0, 0)
        switch_layout.setSpacing(0)
        switch_layout.addWidget(auto_btn)
        switch_layout.addWidget(custom_btn)
        switch_layout.addStretch(1)
        section_layout.addWidget(switch_row)

        # --- Auto view: supply mode + summary + bank run + Clear inventory ---
        auto_layout = QVBoxLayout(auto_view)
        auto_layout.setContentsMargins(0, 2, 0, 0)
        auto_layout.setSpacing(6)

        supply_mode_row = QWidget()
        supply_mode_layout = QHBoxLayout(supply_mode_row)
        supply_mode_layout.setContentsMargins(0, 0, 0, 0)
        supply_mode_layout.setSpacing(8)
        supply_mode_label = QLabel("Supply mode")
        supply_mode_label.setStyleSheet("color: palette(text);")
        supply_mode_combo = QComboBox()
        supply_mode_combo.setObjectName(f"combatPackModeCombo{name_suffix}")
        for _label, _mode_id in (("Balanced", "balanced"), ("Max output", "max_output"), ("Max safety", "max_safety")):
            supply_mode_combo.addItem(_label, _mode_id)
        supply_mode_combo.setCurrentIndex(max(0, supply_mode_combo.findData(str(player_data.get("combat_pack_mode", "balanced")))))

        def _on_pack_mode(_index: int) -> None:
            if on_set_combat_pack_mode is not None:
                on_set_combat_pack_mode(supply_mode_combo.currentData() or "balanced")
            _refresh_carried_sections()

        supply_mode_combo.currentIndexChanged.connect(_on_pack_mode)
        supply_mode_layout.addWidget(supply_mode_label)
        supply_mode_layout.addWidget(supply_mode_combo, 1)
        supply_mode_row.setVisible(bool(carried_auto_is_combat))
        auto_layout.addWidget(supply_mode_row)

        def _auto_summary_text() -> str:
            if get_carried_auto_summary is not None:
                text = str(get_carried_auto_summary() or "")
                if text:
                    return text
            return _combat_loadout_summary_text(player_data)

        def _auto_bank_run_text() -> str:
            if get_carried_bank_run_summary is not None:
                text = str(get_carried_bank_run_summary() or "")
                if text:
                    return text
            return _combat_bank_run_text()

        supply_summary = QLabel(_auto_summary_text())
        supply_summary.setObjectName(f"combatLoadoutSummaryLabel{name_suffix}")
        supply_summary.setWordWrap(True)
        supply_summary.setStyleSheet(f"color: {dim_text_css(supply_summary)};")
        auto_layout.addWidget(supply_summary)

        bank_run_label = QLabel(_auto_bank_run_text())
        bank_run_label.setObjectName(f"combatBankRunLabel{name_suffix}")
        bank_run_label.setWordWrap(True)
        bank_run_label.setStyleSheet(f"color: {dim_text_css(bank_run_label)};")
        auto_layout.addWidget(bank_run_label)

        clear_inv_btn = QPushButton("Clear inventory")
        clear_inv_btn.setObjectName(f"combatClearInventoryButton{name_suffix}")
        clear_inv_btn.setStyleSheet("QPushButton { padding: 2px 10px; }")
        clear_inv_btn.setEnabled(on_unload_combat_loadout is not None)
        clear_inv_btn.setVisible(bool(carried_auto_is_combat))

        def _on_clear_inventory(_checked=False) -> None:
            if on_unload_combat_loadout is not None and on_unload_combat_loadout():
                _refresh_equipment_views(refresh_visible_skill=True)
            _refresh_carried_sections()

        clear_inv_btn.clicked.connect(_on_clear_inventory)
        clear_inv_row = QWidget()
        clear_inv_layout = QHBoxLayout(clear_inv_row)
        clear_inv_layout.setContentsMargins(0, 0, 0, 0)
        clear_inv_layout.addWidget(clear_inv_btn)
        clear_inv_layout.addStretch(1)
        clear_inv_row.setVisible(bool(carried_auto_is_combat))
        auto_layout.addWidget(clear_inv_row)
        section_layout.addWidget(auto_view)

        def _refresh_auto_view() -> None:
            supply_summary.setText(_auto_summary_text())
            bank_run_label.setText(_auto_bank_run_text())
            _mode = str(player_data.get("combat_pack_mode", "balanced"))
            supply_mode_combo.blockSignals(True)
            supply_mode_combo.setCurrentIndex(max(0, supply_mode_combo.findData(_mode)))
            supply_mode_combo.blockSignals(False)

        carried_section_refreshers.append(_refresh_auto_view)

        # --- Custom view: hand-arranged 28-slot grid + Clear layout ---
        custom_layout = QVBoxLayout(custom_view)
        custom_layout.setContentsMargins(0, 2, 0, 0)
        custom_layout.setSpacing(6)

        _CARRIED_CELL_SIZE = 44
        _CARRIED_CELL_SPACING = 4
        _CARRIED_GRID_COLS = 4
        _CARRIED_GRID_ROWS = inventory_pure.CARRIED_CAPACITY // _CARRIED_GRID_COLS

        cell_buttons: list = []
        cell_items: list = [None] * inventory_pure.CARRIED_CAPACITY

        grid_container = QWidget()
        grid_container.setObjectName(f"carriedLayoutGrid{name_suffix}")
        grid_layout = QGridLayout(grid_container)
        grid_layout.setContentsMargins(0, 4, 0, 4)
        grid_layout.setSpacing(_CARRIED_CELL_SPACING)
        for i in range(inventory_pure.CARRIED_CAPACITY):
            cell_btn = QPushButton()
            cell_btn.setObjectName(f"carriedLayoutCell{name_suffix}::{i}")
            cell_btn.setFlat(True)
            cell_btn.setFixedSize(_CARRIED_CELL_SIZE, _CARRIED_CELL_SIZE)

            def _on_cell_clicked(_checked=False, idx=i):
                name = cell_items[idx]
                if name:
                    _prompt_set_pack_quantity(name, cell_buttons[idx])
                else:
                    _prompt_add_to_pack()

            cell_btn.clicked.connect(_on_cell_clicked)
            grid_layout.addWidget(cell_btn, i // _CARRIED_GRID_COLS, i % _CARRIED_GRID_COLS)
            cell_buttons.append(cell_btn)
        # A plain QWidget's default (Preferred) size policy lets a parent
        # QVBoxLayout compress it below its sizeHint when the dialog is short on
        # room — that would clip a 7-row grid of fixed-size buttons down to a
        # sliver. Fixed policy + an exact sizeHint-matching size guarantees all 28
        # cells always get their real, non-negotiable geometry.
        grid_container.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)
        _grid_margins = grid_layout.contentsMargins()
        grid_container.setFixedSize(
            _CARRIED_GRID_COLS * _CARRIED_CELL_SIZE + (_CARRIED_GRID_COLS - 1) * _CARRIED_CELL_SPACING
            + _grid_margins.left() + _grid_margins.right(),
            _CARRIED_GRID_ROWS * _CARRIED_CELL_SIZE + (_CARRIED_GRID_ROWS - 1) * _CARRIED_CELL_SPACING
            + _grid_margins.top() + _grid_margins.bottom(),
        )
        grid_row = QWidget()
        grid_row_layout = QHBoxLayout(grid_row)
        grid_row_layout.setContentsMargins(0, 0, 0, 0)
        grid_row_layout.addWidget(grid_container)
        grid_row_layout.addStretch(1)
        custom_layout.addWidget(grid_row)

        pack_hint = QLabel(
            "Click an empty slot to choose an item. Click a filled slot, or "
            "right-click a Bank item, to set its carried quantity."
        )
        pack_hint.setWordWrap(True)
        pack_hint.setStyleSheet(f"color: {dim_text_css(container)}; font-size: 10px;")
        custom_layout.addWidget(pack_hint)

        clear_layout_btn = QPushButton("Clear layout")
        clear_layout_btn.setObjectName(f"carriedLayoutClearButton{name_suffix}")
        clear_layout_btn.setStyleSheet("QPushButton { padding: 2px 10px; }")

        def _on_clear_layout(_checked=False) -> None:
            if on_clear_carried_layout is not None:
                on_clear_carried_layout()
            _refresh_carried_layout_grid()

        clear_layout_btn.clicked.connect(_on_clear_layout)
        clear_layout_row = QWidget()
        clear_layout_row_layout = QHBoxLayout(clear_layout_row)
        clear_layout_row_layout.setContentsMargins(0, 0, 0, 0)
        clear_layout_row_layout.addWidget(clear_layout_btn)
        clear_layout_row_layout.addStretch(1)
        custom_layout.addWidget(clear_layout_row)
        section_layout.addWidget(custom_view)

        def _refresh_grid() -> None:
            if get_carried_layout_cells is not None:
                cells = tuple(get_carried_layout_cells())
            else:
                cells = ((None, 0),) * inventory_pure.CARRIED_CAPACITY
            for idx, cell_button in enumerate(cell_buttons):
                item_name, count = cells[idx] if idx < len(cells) else (None, 0)
                cell_items[idx] = item_name
                if item_name:
                    count = int(count)
                    cell_button.setText(f"{item_name}\n×{count}" if count > 1 else str(item_name))
                    suffix = f" ×{count}" if count > 1 else ""
                    cell_button.setToolTip(f"{item_name}{suffix} — click to set quantity")
                    cell_button.setEnabled(on_set_carried_layout_quantity is not None)
                    cell_button.setStyleSheet(_CARRIED_CELL_FILLED_CSS)
                else:
                    cell_button.setText("+")
                    cell_button.setToolTip("Empty slot — click to add a bank item")
                    cell_button.setEnabled(on_set_carried_layout_quantity is not None)
                    cell_button.setStyleSheet(_CARRIED_CELL_EMPTY_CSS)

        carried_grid_refreshers.append(_refresh_grid)

        _apply_mode(bool(carried_mode_state["advanced"]))
        _refresh_grid()
        _refresh_auto_view()
        return container

    # The per-enemy loot filter stays on the Equipment tab (with the live combat
    # controls); the Bank keeps a pointer so players still discover it from here.
    carried_pointer = QLabel("Set per-enemy loot filters in the Equipment tab.")
    carried_pointer.setObjectName("carriedEquipmentPointer")
    carried_pointer.setWordWrap(True)
    carried_pointer.setStyleSheet(f"color: {dim_text_css(carried_pointer)};")
    carried_pointer.setVisible(bool(carried_auto_is_combat))
    cb_layout.addWidget(carried_pointer)

    carried_summary = QLabel(_carried_panel_summary_text())
    carried_summary.setObjectName("carriedInventorySummary")
    carried_summary.setWordWrap(True)
    carried_summary.setStyleSheet(f"color: {dim_text_css(carried_summary)};")
    cb_layout.addWidget(carried_summary)

    # A second carried-pack section (secondary instance) so the Auto|Custom
    # switch and the 28-slot grid are reachable right here on the Bank tab.
    cb_layout.addWidget(_build_carried_pack_section(primary=False))

    def _toggle_carried_body(checked: bool) -> None:
        carried_body.setVisible(bool(checked))
        carried_header.setText(("▾  Carried inventory") if checked else ("▸  Carried inventory"))

    carried_header.toggled.connect(_toggle_carried_body)

    def _refresh_carried_panel() -> None:
        carried_summary.setText(_carried_panel_summary_text())
        _refresh_carried_sections()
        _refresh_carried_layout_grid()

    bk_layout.addWidget(carried_header)
    bk_layout.addWidget(carried_body)

    bank_filter_bar = CatalogFilterBar(
        placeholder="Search Bank items or categories…",
        search_object_name="bankSearchInput",
        parent=bank_tab,
    )
    bk_layout.addWidget(bank_filter_bar)

    bank_list = QListWidget()
    bank_list.setIconSize(QSize(28, 28))
    bank_list.setAlternatingRowColors(True)
    bank_list.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
    # Inventory is grouped by item-registry category (Ores, Logs, ..., Fletched,
    # Materials) so newly registered items appear cleanly without per-skill
    # branches. Each item's icon comes from its ItemDefinition.asset_path, with a
    # legacy image-map fallback for anything predating the manifest.
    _legacy_icon_maps = (
        ORE_IMAGES,
        TREE_IMAGES,
        BAR_IMAGES,
        GEM_IMAGES,
        CRAFTED_ITEM_IMAGES,
        FLETCHED_ITEM_IMAGES,
        FIREMAKING_ITEM_IMAGES,
        FISHING_ITEM_IMAGES,
        COOKING_ITEM_IMAGES,
    )

    def _bank_icon_path(item_name: str, asset_path) -> Optional[str]:
        if asset_path and os.path.exists(asset_path):
            return asset_path
        for image_map in _legacy_icon_maps:
            candidate = image_map.get(item_name)
            if candidate and os.path.exists(candidate):
                return candidate
        return None

    def _make_header_item(label: str, marker: str) -> QListWidgetItem:
        header = QListWidgetItem(label)
        header.setFlags(Qt.ItemFlag.NoItemFlags)
        header_font = header.font()
        header_font.setBold(True)
        header.setFont(header_font)
        header.setData(Qt.ItemDataRole.UserRole, marker)
        return header

    # Equip/Unequip mutate player_data via the backend handlers, so the Bank
    # inventory and the Equipment tab must both re-read after an action. The
    # Equipment tab registers its repaint here so a single call refreshes both
    # without rebuilding the whole dialog.
    _equipment_refreshers: list = []

    def _refresh_equipment_views(*, refresh_visible_skill: bool = False) -> None:
        _populate_bank_list()
        _populate_death_office()
        for refresher in _equipment_refreshers:
            refresher()
        for refresher in _combat_setup_refreshers:
            refresher()
        if refresh_visible_skill or state.get("skill") == _COMBAT_HUB_NAME:
            _render_panel()

    # The Shop tab reaches the Bank/Equipment/Skills gear views through this key.
    ctx.refreshers["gear"] = _refresh_equipment_views

    def _full_urn_tooltip(info: dict) -> str:
        skill = get_skill(str(info.get("skill_id", "")))
        skill_name = skill.display_name if skill is not None else str(info.get("skill_id", "")).title()
        xp = float(info.get("teleport_xp", 0.0) or 0.0)
        if info.get("eligible"):
            target_id = str(info.get("target_id", ""))
            return f"Full urn — teleport for {xp:g} {skill_name} XP.\nReady in the carried pack for current target: {target_id}."
        return (
            f"Full urn — teleport for {xp:g} {skill_name} XP.\n"
            f"Add it to the carried pack for the current {skill_name} target to enable Teleport urn."
        )

    def _populate_bank_list() -> None:
        _refresh_carried_panel()
        bank_list.clear()
        inv = player_data.get("inventory", {}) or {}
        groups = grouped_inventory(inv)
        total_count = sum(len(rows) for _category_label, rows in groups)
        visible_count = 0
        if not groups:
            empty = QListWidgetItem("Your bank is empty — train a skill to gather items.")
            empty.setFlags(Qt.ItemFlag.NoItemFlags)
            bank_list.addItem(empty)
        for category_label, rows in groups:
            filtered_rows = tuple(
                row
                for row in rows
                if bank_filter_bar.matches_text(row[0], category_label)
            )
            if not filtered_rows:
                continue
            bank_list.addItem(_make_header_item(category_label, "__header__"))
            for item_name, amount, asset_path in filtered_rows:
                visible_count += 1
                li = QListWidgetItem(f"{item_name} x{amount}")
                icon_path = _bank_icon_path(item_name, asset_path)
                if icon_path:
                    li.setIcon(QIcon(icon_path))
                # The plain item name is stashed on every inventory row so the
                # right-click handler can resolve equippability without parsing
                # the "Name xN" label back apart.
                li.setData(Qt.ItemDataRole.UserRole, item_name)
                urn_info = full_urn_teleport_info_pure(player_data, item_name)
                if urn_info is not None:
                    li.setData(Qt.ItemDataRole.UserRole + 1, urn_info["urn_id"])
                    li.setToolTip(_full_urn_tooltip(urn_info))
                elif is_equippable_item(item_name):
                    ok, reason = can_equip_item_pure(item_name, EQUIPMENT_ITEM_DATA, player_data)
                    li.setToolTip(equipment_full_tooltip(item_name, "" if ok else reason))
                bank_list.addItem(li)
        if groups and not visible_count:
            empty = QListWidgetItem("No Bank items match your search.")
            empty.setFlags(Qt.ItemFlag.NoItemFlags)
            bank_list.addItem(empty)
        bank_filter_bar.set_count(visible_count, total_count)

    bank_filter_bar.search_input.textChanged.connect(
        lambda _text: _populate_bank_list()
    )

    claims_box = QWidget()
    claims_box.setObjectName("bankClaimsBox")
    claims_box.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Maximum)
    claims_layout = QVBoxLayout(claims_box)
    claims_layout.setContentsMargins(0, 0, 0, 0)
    claims_layout.setSpacing(6)

    death_office_box = QWidget()
    death_office_box.setObjectName("deathOfficeBox")
    death_office_box.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Maximum)
    death_office_layout = QVBoxLayout(death_office_box)
    death_office_layout.setContentsMargins(0, 0, 0, 0)
    death_office_layout.setSpacing(6)

    def _skill_display(skill_id: str) -> str:
        skill = get_skill(skill_id)
        return skill.display_name if skill is not None else skill_id.replace("_", " ").title()

    def _skill_level(skill_id: str) -> int:
        skill = get_skill(skill_id)
        level_key = skill.level_key if skill is not None else f"{skill_id}_level"
        try:
            return int(player_data.get(level_key, 1))
        except (TypeError, ValueError):
            return 1

    def _claim_skill_tooltip(row: dict) -> str:
        options = tuple(str(skill_id) for skill_id in row.get("skill_options", ()) or ())
        minimum_level = int(row.get("minimum_level", 1) or 1)
        if not options:
            return ""
        if len(options) > 8:
            label = "Any listed skill"
        else:
            label = ", ".join(_skill_display(skill_id) for skill_id in options[:8])
        if minimum_level > 1:
            return f"Choose: {label}. Minimum level: {minimum_level}."
        return f"Choose: {label}."

    def _claim_metadata(row: dict) -> str:
        if str(row.get("claim_type", "item")) == "xp_lamp":
            amount = row.get("xp_amount", 0)
            amount_text = f"{int(amount):,}" if float(amount or 0).is_integer() else f"{float(amount or 0):,.1f}"
            tooltip = _claim_skill_tooltip(row)
            return f"{amount_text} XP lamp" + (f" · {tooltip}" if tooltip else "")
        if str(row.get("claim_type", "item")) == "item_bundle":
            items = tuple(row.get("items", ()) or ())
            preview = []
            for item in items[:3]:
                if isinstance(item, (tuple, list)) and len(item) >= 2:
                    preview.append(f"{item[0]} x{item[1]}")
            if len(items) > len(preview):
                preview.append(f"+{len(items) - len(preview)} more")
            item_count = len(items)
            suffix = f" - {', '.join(preview)}" if preview else ""
            return f"{item_count} item stack{'s' if item_count != 1 else ''}{suffix}"
        return "Ready to claim"

    def _claim_bundle_tooltip(row: dict) -> str:
        items = tuple(row.get("items", ()) or ())
        lines = []
        for item in items:
            if isinstance(item, (tuple, list)) and len(item) >= 2:
                lines.append(f"{item[0]} x{item[1]}")
        return "\n".join(lines)

    def _claim_item_icon_path(row: dict) -> Optional[str]:
        item_name = str(row.get("item_name", row.get("display_name", "")))
        if str(row.get("claim_type", "item")) == "item_bundle":
            items = tuple(row.get("items", ()) or ())
            first = items[0] if items else ()
            if isinstance(first, (tuple, list)) and first and isinstance(first[0], str):
                item_name = first[0]
        definition = _item_def_for(item_name)
        asset_path = definition.asset_path if definition is not None else None
        return _bank_icon_path(item_name, asset_path)

    def _choose_claim_skill(row: dict) -> Optional[str]:
        options = tuple(str(skill_id) for skill_id in row.get("skill_options", ()) or ())
        minimum_level = int(row.get("minimum_level", 1) or 1)
        eligible = [skill_id for skill_id in options if _skill_level(skill_id) >= minimum_level]
        if not eligible:
            QMessageBox.warning(claims_box, "No eligible skill", f"This lamp requires level {minimum_level} in an allowed skill.")
            return None
        labels = [_skill_display(skill_id) for skill_id in eligible]
        choice, ok = QInputDialog.getItem(claims_box, "Claim XP lamp", "Skill:", labels, 0, False)
        if not ok:
            return None
        try:
            return eligible[labels.index(choice)]
        except ValueError:
            return None

    def _populate_claims() -> None:
        _clear_layout(claims_layout)
        rows = claim_rows_pure(player_data, CLAIM_DATA)
        unclaimed = [row for row in rows if not row.get("claimed")]
        actionable = [row for row in unclaimed if row.get("eligible")]
        if not rows:
            claims_box.setVisible(False)
            return
        claims_box.setVisible(True)
        header = QLabel("Bank Claims")
        header.setObjectName("bankClaimsHeader")
        header.setStyleSheet("font-weight: 600; color: palette(text);")
        claims_layout.addWidget(header)
        max_claim_height = header.sizeHint().height()

        # Locked claims render nothing at all: a reward the player cannot claim
        # is not actionable, so a locked-only save is "caught up" here.
        if not actionable:
            empty = QLabel("All Bank Claims caught up.")
            empty.setObjectName("bankClaimsCaughtUp")
            empty.setStyleSheet(f"color: {dim_text_css(empty)};")
            claims_layout.addWidget(empty)
            claims_box.setMaximumHeight(max_claim_height + claims_layout.spacing() + empty.sizeHint().height() + 4)
            return

        rows_host = QWidget()
        rows_host.setObjectName("bankClaimsRows")
        rows_layout = QVBoxLayout(rows_host)
        rows_layout.setContentsMargins(0, 0, 0, 0)
        rows_layout.setSpacing(4)
        rendered_rows = 0

        for row in actionable:
            claim_row = QWidget()
            claim_row.setObjectName("bankClaimRow")
            crl = QHBoxLayout(claim_row)
            crl.setContentsMargins(6, 4, 6, 4)
            crl.setSpacing(8)
            item_name = str(row.get("item_name", row.get("display_name", "")))
            claim_type = str(row.get("claim_type", "item"))
            icon_label = QLabel()
            icon_label.setObjectName("bankClaimIcon")
            icon_label.setFixedSize(28, 28)
            icon_label.setStyleSheet("background: rgba(255, 255, 255, 0.08); border: 1px solid palette(mid); border-radius: 4px;")
            icon_path = _claim_item_icon_path(row)
            if icon_path:
                icon_label.setPixmap(QIcon(icon_path).pixmap(24, 24))
                icon_label.setStyleSheet("")
            if claim_type == "xp_lamp":
                title_text = str(row.get("display_name", item_name))
            elif claim_type == "item_bundle":
                title_text = str(row.get("display_name", item_name))
            else:
                title_text = f"{row.get('display_name', item_name)} x{row.get('quantity', 1)}"
            copy = QWidget()
            copy_layout = QVBoxLayout(copy)
            copy_layout.setContentsMargins(0, 0, 0, 0)
            copy_layout.setSpacing(1)
            label = QLabel(title_text)
            label.setObjectName("bankClaimTitle")
            label.setStyleSheet("color: palette(text); font-weight: 600;")
            if claim_type == "xp_lamp":
                label.setToolTip(_claim_skill_tooltip(row))
            metadata = QLabel(_claim_metadata(row))
            metadata.setObjectName("bankClaimMetadata")
            metadata.setStyleSheet(f"color: {dim_text_css(metadata)};")
            if claim_type == "xp_lamp":
                metadata.setToolTip(_claim_skill_tooltip(row))
            elif claim_type == "item_bundle":
                bundle_tooltip = _claim_bundle_tooltip(row)
                label.setToolTip(bundle_tooltip)
                metadata.setToolTip(bundle_tooltip)
            copy_layout.addWidget(label)
            copy_layout.addWidget(metadata)
            claim_btn = QPushButton("Claim")
            claim_btn.setObjectName("bankClaimAction")
            if claim_type == "xp_lamp":
                claim_btn.setText("Choose skill")
                claim_btn.setToolTip(_claim_skill_tooltip(row))

            def _do_claim(_checked: bool = False, claim_id=row.get("claim_id"), claim_row=row) -> None:
                if on_claim_reward is None or not isinstance(claim_id, str):
                    return
                selected_skill_id = None
                if str(claim_row.get("claim_type", "item")) == "xp_lamp":
                    selected_skill_id = _choose_claim_skill(claim_row)
                    if selected_skill_id is None:
                        return
                if on_claim_reward(claim_id, selected_skill_id):
                    _populate_claims()
                    _refresh_equipment_views()

            claim_btn.clicked.connect(_do_claim)
            crl.addWidget(icon_label)
            crl.addWidget(copy)
            crl.addStretch(1)
            crl.addWidget(claim_btn)
            rows_layout.addWidget(claim_row)
            rendered_rows += 1

        if rendered_rows:
            scroll = QScrollArea()
            scroll.setObjectName("bankClaimsScrollArea")
            scroll.setWidgetResizable(True)
            scroll.setStyleSheet("QScrollArea#bankClaimsScrollArea { border: none; }")
            scroll.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
            scroll.setWidget(rows_host)
            row_height = max(rows_host.sizeHint().height() // rendered_rows, 42)
            scroll_height = (row_height * 3) + 10
            scroll.setMaximumHeight(scroll_height)
            claims_layout.addWidget(scroll)
            max_claim_height += claims_layout.spacing() + scroll_height
        else:
            rows_host.deleteLater()

        claims_box.setMaximumHeight(max_claim_height + 4)

    def _death_office_items_tooltip(items: tuple) -> str:
        if not items:
            return ""
        counts: dict[str, int] = {}
        for item_name in items:
            if isinstance(item_name, str):
                counts[item_name] = counts.get(item_name, 0) + 1
        return "\n".join(f"{item_name} x{amount}" for item_name, amount in counts.items())

    def _populate_death_office() -> None:
        _clear_layout(death_office_layout)
        summary = combat_death_office_summary_pure(player_data)
        items = tuple(summary.get("items", ()) or ())
        if not items:
            death_office_box.setVisible(False)
            return
        death_office_box.setVisible(True)
        header = QLabel("Death's Office")
        header.setObjectName("deathOfficeHeader")
        header.setStyleSheet("font-weight: 600; color: palette(text);")
        death_office_layout.addWidget(header)

        row = QWidget()
        row.setObjectName("deathOfficeRow")
        row_layout = QHBoxLayout(row)
        row_layout.setContentsMargins(6, 4, 6, 4)
        row_layout.setSpacing(8)

        first_item = next((item for item in items if isinstance(item, str)), "")
        icon_label = QLabel()
        icon_label.setObjectName("deathOfficeIcon")
        icon_label.setFixedSize(28, 28)
        icon_label.setStyleSheet("background: rgba(255, 255, 255, 0.08); border: 1px solid palette(mid); border-radius: 4px;")
        if first_item:
            definition = _item_def_for(first_item)
            asset_path = definition.asset_path if definition is not None else None
            icon_path = _bank_icon_path(first_item, asset_path)
            if icon_path:
                icon_label.setPixmap(QIcon(icon_path).pixmap(24, 24))
                icon_label.setStyleSheet("")

        copy = QWidget()
        copy_layout = QVBoxLayout(copy)
        copy_layout.setContentsMargins(0, 0, 0, 0)
        copy_layout.setSpacing(1)
        item_count = int(summary.get("item_count", len(items)) or len(items))
        title = QLabel(f"{item_count} reclaimed gear item{'s' if item_count != 1 else ''}")
        title.setObjectName("deathOfficeTitle")
        title.setStyleSheet("color: palette(text); font-weight: 600;")
        tooltip = _death_office_items_tooltip(items)
        if tooltip:
            title.setToolTip(tooltip)
        cost = int(summary.get("reclaim_cost", 0) or 0)
        coins = int(summary.get("coins", 0) or 0)
        metadata = QLabel(f"Cost: {cost:,} Coins · Bank: {coins:,} Coins")
        metadata.setObjectName("deathOfficeMetadata")
        metadata.setStyleSheet(f"color: {dim_text_css(metadata)};")
        if tooltip:
            metadata.setToolTip(tooltip)
        copy_layout.addWidget(title)
        copy_layout.addWidget(metadata)

        reclaim_btn = QPushButton("Reclaim")
        reclaim_btn.setObjectName("deathOfficeReclaimAction")
        reclaim_btn.setEnabled(bool(summary.get("can_reclaim")) and on_reclaim_death_office is not None)
        if not summary.get("can_reclaim"):
            reclaim_btn.setToolTip(f"Need {cost:,} Coins to reclaim this gear.")

        def _do_reclaim(_checked: bool = False) -> None:
            if on_reclaim_death_office is None:
                return
            if on_reclaim_death_office():
                _refresh_equipment_views()

        reclaim_btn.clicked.connect(_do_reclaim)
        row_layout.addWidget(icon_label)
        row_layout.addWidget(copy)
        row_layout.addStretch(1)
        row_layout.addWidget(reclaim_btn)
        death_office_layout.addWidget(row)
        death_office_box.setMaximumHeight(
            header.sizeHint().height() + death_office_layout.spacing() + row.sizeHint().height() + 4
        )

    def _build_bank_equip_menu(item_name: str) -> "QMenu":
        """Right-click menu for an inventory row.

        Exposed as a builder (rather than only an inline exec) so the offscreen
        tests can assert action state without spawning a native popup.
        """
        menu = QMenu(bank_list)
        if is_equippable_item(item_name):
            ok, reason = can_equip_item_pure(item_name, EQUIPMENT_ITEM_DATA, player_data)
            action = menu.addAction("Equip" if ok else f"Equip ({reason})")
            action.setEnabled(bool(ok) and on_equip_item is not None)
            if not ok and reason:
                action.setToolTip(reason)

            def _do_equip(_checked: bool = False) -> None:
                if on_equip_item is None:
                    return
                if on_equip_item(item_name):
                    _refresh_equipment_views()

            action.triggered.connect(_do_equip)
            menu.addSeparator()

        amount = int((player_data.get("inventory", {}) or {}).get(item_name, 0) or 0)

        try:
            from ..core.constants import CONSUMABLE_DATA  # type: ignore
        except Exception:
            CONSUMABLE_DATA = {}
        if item_name in CONSUMABLE_DATA:
            verb = str(CONSUMABLE_DATA[item_name].get("verb", "Drink"))
            consume_action = menu.addAction(f"{verb} {item_name}")
            consume_action.setEnabled(amount > 0 and on_consume_item is not None)

            def _do_consume(_checked: bool = False) -> None:
                if on_consume_item is None:
                    return
                result = on_consume_item(item_name)
                if result:
                    _refresh_equipment_views()
                    message = str(result.get("message", ""))
                    if message:
                        QMessageBox.information(bank_list, item_name, message)

            consume_action.triggered.connect(_do_consume)
            menu.addSeparator()

        if item_name in ITEM_PACK_DATA:
            content_item = str(ITEM_PACK_DATA[item_name]["content_item"])
            per_pack = int(ITEM_PACK_DATA[item_name]["content_quantity"])
            open_action = menu.addAction(f"Open {item_name}")
            open_action.setEnabled(amount > 0 and on_open_item_pack is not None)
            open_action.setToolTip(f"Receive {per_pack:,} {content_item}.")

            def _do_open(_checked: bool = False, open_all: bool = False) -> None:
                if on_open_item_pack is None:
                    return
                if on_open_item_pack(item_name, open_all):
                    _refresh_equipment_views()

            open_action.triggered.connect(_do_open)
            if amount > 1:
                open_all_action = menu.addAction(f"Open all ({amount})")
                open_all_action.setEnabled(on_open_item_pack is not None)
                open_all_action.setToolTip(f"Receive {amount * per_pack:,} {content_item}.")
                open_all_action.triggered.connect(lambda _checked=False: _do_open(open_all=True))
            menu.addSeparator()

        if item_name == "Rogue kit":
            convert_menu = menu.addMenu("Convert Rogue kit to")
            convert_menu.setEnabled(
                amount > 0 and on_convert_rogue_kit is not None
            )
            for output_item in ROGUE_KIT_OUTPUTS:
                convert_action = convert_menu.addAction(output_item)
                convert_action.setObjectName(
                    "rogueKit" + output_item.replace(" ", "") + "Action"
                )

                def _do_convert(
                    _checked: bool = False,
                    chosen_item: str = output_item,
                ) -> None:
                    if on_convert_rogue_kit is None:
                        return
                    if on_convert_rogue_kit(chosen_item):
                        _refresh_equipment_views()

                convert_action.triggered.connect(_do_convert)
            menu.addSeparator()

        urn_info = full_urn_teleport_info_pure(player_data, item_name)
        if urn_info is not None:
            teleport_action = menu.addAction("Teleport urn")
            teleport_action.setObjectName("teleportTrainingUrnAction")
            teleport_action.setData(urn_info["urn_id"])
            teleport_action.setToolTip(_full_urn_tooltip(urn_info))
            teleport_action.setEnabled(bool(urn_info["eligible"]) and on_teleport_training_urn is not None)

            def _do_teleport(_checked: bool = False, urn_id=str(urn_info["urn_id"])) -> None:
                if on_teleport_training_urn is None:
                    return
                if on_teleport_training_urn(urn_id):
                    _refresh_equipment_views(refresh_visible_skill=True)

            teleport_action.triggered.connect(_do_teleport)
            menu.addSeparator()

        if carried_mode_state["advanced"] and on_set_carried_layout_quantity is not None:
            set_layout_action = menu.addAction("Set carried quantity…")
            set_layout_action.triggered.connect(
                lambda _checked=False, name=item_name: _prompt_set_pack_quantity(name, bank_list)
            )
            menu.addSeparator()

        discard_action = menu.addAction("Discard X…")
        discard_action.setEnabled(amount > 0 and on_discard_item is not None)
        discard_action.setToolTip(f"Choose how many of the {amount} in your Bank to discard.")

        def _do_discard(_checked: bool = False) -> None:
            if on_discard_item is None:
                return
            quantity, ok = QInputDialog.getInt(
                bank_list,
                "Discard from Bank",
                f"{item_name} quantity:",
                amount,
                1,
                amount,
                1,
            )
            if ok and on_discard_item(item_name, quantity):
                _refresh_equipment_views()

        discard_action.triggered.connect(_do_discard)
        return menu

    def _bank_context_menu(pos) -> None:
        item = bank_list.itemAt(pos)
        if item is None:
            return
        item_name = item.data(Qt.ItemDataRole.UserRole)
        if not isinstance(item_name, str):
            return
        menu = _build_bank_equip_menu(item_name)
        menu.exec(bank_list.viewport().mapToGlobal(pos))

    bank_list.customContextMenuRequested.connect(_bank_context_menu)
    _populate_death_office()
    bk_layout.addWidget(death_office_box)
    _populate_claims()
    bk_layout.addWidget(claims_box)
    _populate_bank_list()
    bk_layout.addWidget(bank_list, 1)

    # Gear sits in its own pinned panel below the scrollable, striped inventory
    # (the owner wanted it "outside the striped window"). The toolbelt is
    # auto-resolved — best owned tool wins — so we show the active
    # pickaxe/hatchet. Worn equipment now has its own dedicated Equipment tab,
    # so the Bank panel is toolbelt-only.
    gear_list = QListWidget()
    gear_list.setObjectName("gearList")
    gear_list.setIconSize(QSize(28, 28))
    gear_list.setAlternatingRowColors(False)
    gear_list.setSelectionMode(QListWidget.SelectionMode.NoSelection)
    gear_list.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
    gear_list.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)

    def _add_gear_row(text: str, item_name: str) -> None:
        li = QListWidgetItem(text)
        definition = _item_def_for(item_name)
        asset_path = definition.asset_path if definition is not None else None
        icon_path = _bank_icon_path(item_name, asset_path)
        if icon_path:
            li.setIcon(QIcon(icon_path))
        li.setFlags(Qt.ItemFlag.ItemIsEnabled)
        li.setData(Qt.ItemDataRole.UserRole, "__gear__")
        gear_list.addItem(li)

    gear = bank_gear_rows_pure(player_data, MINING_PICKAXE_DATA, WOODCUTTING_AXE_DATA, MINING_BONUS_ITEM_DATA)
    gear_list.addItem(_make_header_item("Toolbelt", "__gear_header__"))
    if gear["toolbelt"]:
        for slot_label, display_name in gear["toolbelt"]:
            _add_gear_row(f"{slot_label}: {display_name}", display_name)
    else:
        empty_tb = QListWidgetItem("No tools yet.")
        empty_tb.setFlags(Qt.ItemFlag.NoItemFlags)
        empty_tb.setData(Qt.ItemDataRole.UserRole, "__gear_empty__")
        gear_list.addItem(empty_tb)
    # Owned upgrades the level gate still blocks. Without this the auto-resolved
    # toolbelt looks like it ignored the purchase.
    for slot_label, display_name, skill_label, required_level in gear["toolbelt_blocked"]:
        blocked = QListWidgetItem(f"{display_name} — needs {skill_label} {required_level}")
        blocked.setToolTip(
            f"You own this {slot_label.lower()}, but it needs {skill_label} level "
            f"{required_level}. It joins your toolbelt automatically at that level."
        )
        blocked.setForeground(dim_text_color(gear_list))
        blocked.setFlags(Qt.ItemFlag.ItemIsEnabled)
        blocked.setData(Qt.ItemDataRole.UserRole, "__gear_blocked__")
        gear_list.addItem(blocked)

    # Hug contents so the panel is a fixed strip, never its own scroller.
    _gear_h = 2 * gear_list.frameWidth() + 6
    for _i in range(gear_list.count()):
        _row_h = gear_list.sizeHintForRow(_i)
        _gear_h += _row_h if _row_h > 0 else 30
    gear_list.setFixedHeight(_gear_h)
    bk_layout.addWidget(gear_list)
    tabs.addTab(bank_tab, "Bank")
    _set_global_tab_icon(bank_tab, "bank_icon.png")
    tabs.setTabToolTip(tabs.indexOf(bank_tab), "View all your items")

